            this.minFlips = minFlips;
        }
    }

    public Result minCostToEval(String expression) {
        return minCostToEvalHelper(expression, 0, expression.length() - 1);
    }

    private Result minCostToEvalHelper(String expression, int start, int end) {
        if (start == end) {
            char c = expression.charAt(start);
            int val = (c == '1') ? 1 : 0;
            return new Result(val, 0);
        }

        if (expression.charAt(start) == '(' && expression.charAt(end) == ')') {
            return minCostToEvalHelper(expression, start + 1, end - 1);
        }

        int minFlips = Integer.MAX_VALUE;
        Result bestResult = null;

        for (int i = start; i < end; i++) {
            char c = expression.charAt(i);
            if (c == '&' || c == '|') {
                Result leftResult = minCostToEvalHelper(expression, start, i - 1);
                Result rightResult = minCostToEvalHelper(expression, i + 1, end);

                int val = (c == '&') ? (leftResult.val & rightResult.val) : (leftResult.val | rightResult.val);
                int flips = leftResult.minFlips + rightResult.minFlips;

                if (val == 0) {
                    flips++;
                } else {
                    flips++;
                }

                if (flips < minFlips) {
                    minFlips = flips;
                    bestResult = new Result(val, flips);
                } else if (flips == minFlips) {
                    if (bestResult.val != val) {
                        bestResult = new Result(val, flips);
                    }
                }
            }
        }

        if (bestResult == null) {
            char c = expression.charAt(start);
            int val = (c == '1') ? 1 : 0;
            return new Result(val, 0);
        }

        return bestResult;
    }
}

