        int j = 0;
        int earliestYear = 0;

        while (i < birth.length && j < death.length) {
            if (birth[i] <= death[j]) {
                currentPopulation++;
                if (currentPopulation > maxPopulation) {
                    maxPopulation = currentPopulation;
                    earliestYear = birth[i];
