                if (box[i][j] == '#') {
                    stones++;
                } else {
                    for (int k = 0; k < stones; k++) {
                        rotatedBox.get(j).set(m - 1 - i, '#');
                    }
                    stones = 0;
                }
            }
            for (int k = 0; k < stones; k++) {
                rotatedBox.get(j).set(m - 1, '#');
            }
        }

        char[][] result = new char[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
