public class Solution {
    public int longestBeautifulSubstring(String word) {
        int n = word.length();
        int maxLength = 0;

        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                String sub = word.substring(i, j + 1);
