        if (s.length() < 5) {
            return false;
        }

        int aCount = 0;
        int eCount = 0;
        int iCount = 0;
        int oCount = 0;
        int uCount = 0;

        for (char c : s.toCharArray()) {
            if (c == 'a') {
                aCount++;
            } else if (c == 'e') {
                eCount++;
            } else if (c == 'i') {
                iCount++;
            } else if (c == 'o') {
                oCount++;
            } else if (c == 'u') {
                uCount++;
            } else {
                return false;
            }
        }

        if (aCount == 0 || eCount == 0 || iCount == 0 || oCount == 0 || uCount == 0) {
            return false;
        }

        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < s.charAt(i - 1)) {
