public class Solution {
    public int[] assignTasks(int[] servers, int[] tasks) {
        int n = servers.length;
        int m = tasks.length;
        int[] ans = new int[m];
        PriorityQueue<Integer> availableServers = new PriorityQueue<>((a, b) -> {
            if (servers[a] != servers[b]) {
                return servers[a] - servers[b];
            }
            return a - b;
        });
        for (int i = 0; i < n; i++) {
            availableServers.offer(i);
        }
        PriorityQueue<int[]> waitQueue = new PriorityQueue<>((a, b) -> {
            if (a[1] != b[1]) {
                return a[1] - b[1];
            }
            return a[0] - b[0];
        });
        int time = 0;
        int taskIndex = 0;
        while (taskIndex < m || !waitQueue.isEmpty() || !availableServers.isEmpty()) {
            if (availableServers.isEmpty() && waitQueue.isEmpty()) {
                time++;
                continue;
            }
            while (taskIndex < m && time < tasks[taskIndex] + time) {
                waitQueue.offer(new int[]{taskIndex, tasks[taskIndex]});
                taskIndex++;
            }
            if (waitQueue.isEmpty()) {
                time++;
                continue;
            }
            if (availableServers.isEmpty()) {
                time = waitQueue.peek()[1] + time;
                time = Math.max(time, waitQueue.peek()[1]);
            }
            int[] task = waitQueue.poll();
            int serverIndex = availableServers.poll();
            ans[task[0]] = serverIndex;
            time += tasks[task[0]];
            availableServers.offer(serverIndex);
        }
        return ans;
    }
}

