public class Solution {
    public int reinitializePermutation(int n) {
        int[] perm = new int[n];
        for (int i = 0; i < n; i++) {
            perm[i] = i;
        }

        int operations = 0;
        while (true) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                if (i % 2 == 0) {
                    arr[i] = perm[i / 2];
                } else {
                    arr[i] = perm[n / 2 + (i - 1) / 2];
                }
            }

            for (int i = 0; i < n; i++) {
                perm[i] = arr[i];
            }

            operations++;

            boolean isInitialized = true;
            for (int i = 0; i < n; i++) {
                if (perm[i] != i) {
                    isInitialized = false;
                    break;
                }
            }

            if (isInitialized) {
                return operations;
            }
        }
    }
}

