public class Solution {
    public int maximumRemovals(String s, String p, int[] removable) {
        int left = 0;
        int right = removable.length;
        int ans = 0;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            String tempS = removeChars(s, removable, mid);
            if (isSubsequence(p, tempS)) {
                ans = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return ans;
    }

    private String removeChars(String s, int[] removable, int k) {
        StringBuilder sb = new StringBuilder(s);
        for (int i = 0; i < k; i++) {
            sb.deleteCharAt(removable[i]);
        }
        return sb.toString();
    }

    private boolean isSubsequence(String p, String s) {
        int i = 0;
        int j = 0;
        while (i < p.length() && j < s.length()) {
            if (p.charAt(i) == s.charAt(j)) {
                i++;
            }
            j++;
        }
        return i == p.length();
    }
}

