public class Solution {
    public int minSideJumps(int[] obstacles) {
        int n = obstacles.length;
        int[] dp = new int[3];
        for (int i = 0; i < 3; i++) {
            dp[i] = 1;
        }

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < 3; j++) {
                if (obstacles[i] == j) {
                    dp[j] = Integer.MAX_VALUE;
                } else {
                    dp[j] = dp[j] + 1;
                }
            }

            for (int j = 0; j < 3; j++) {
                if (obstacles[i] == j) {
                    dp[j] = Integer.MAX_VALUE;
                } else {
                    dp[j] = Math.min(dp[j], dp[(j + 1) % 3] + 1);
                    dp[j] = Math.min(dp[j], dp[(j + 2) % 3] + 1);
                }
            }
        }

        int minJumps = Integer.MAX_VALUE;
        for (int i = 0; i < 3; i++) {
            minJumps = Math.min(minJumps, dp[i]);
        }

