        if (s.length() == 0) {
            return true;
        }

        for (int i = 1; i < s.length(); i++) {
            String current = s.substring(0, i);
            long currentNum = Long.parseLong(current);
            if (currentNum < prevNum && (prevNum - currentNum == 1)) {
                if (canSplit(s.substring(i), currentNum)) {
                    return true;
                }
            }
        }

        return false;
    }
}

