import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int racecar(int target) {
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, 1, 0}); // position, speed, steps
        boolean[][] visited = new boolean[2 * target + 1][2];

        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int pos = curr[0];
            int speed = curr[1];
            int steps = curr[2];

            if (pos == target) {
                return steps;
            }

            if (Math.abs(pos - target) > target && steps > 10000) {
                continue;
            }

            if (visited[pos + target][speed > 0 ? 1 : 0]) {
                continue;
            }
            visited[pos + target][speed > 0 ? 1 : 0] = true;

            // Accelerate
            int newPosA = pos + speed;
            int newSpeedA = speed > 0 ? 2 : -2;
            if (Math.abs(newPosA - target) < target * 2) {
                q.offer(new int[]{newPosA, newSpeedA, steps + 1});
            }

            // Reverse
            int newSpeedR = speed > 0 ? -1 : 1;
            q.offer(new int[]{pos, newSpeedR, steps + 1});
        }

        return -1;
    }
}

