import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> eventualSafeNodes(int[][] graph) {
        int n = graph.length;
        int[] color = new int[n]; // 0: unvisited, 1: visiting, 2: visited (safe)
        List<Integer> safeNodes = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (dfs(graph, i, color)) {
                safeNodes.add(i);
            }
        }

        safeNodes.sort(null);
        return safeNodes;
    }

    private boolean dfs(int[][] graph, int node, int[] color) {
        if (color[node] != 0) {
            return color[node] == 2;
        }

        color[node] = 1; // Mark as visiting

        for (int neighbor : graph[node]) {
            if (color[neighbor] == 1 || !dfs(graph, neighbor, color)) {
                return false; // Cycle detected or neighbor is not safe
            }
        }

        color[node] = 2; // Mark as visited (safe)
        return true;
    }
}

