public class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int count = 0;

        for (int i = 0; i <= rows - 3; i++) {
            for (int j = 0; j <= cols - 3; j++) {
                if (isMagicSquare(grid, i, j)) {
                    count++;
                }
            }
        }

        return count;
    }

    private boolean isMagicSquare(int[][] grid, int rowStart, int colStart) {
        int sum = 0;
        Set<Integer> numbers = new HashSet<>();

        for (int i = rowStart; i < rowStart + 3; i++) {
            for (int j = colStart; j < colStart + 3; j++) {
                int num = grid[i][j];
                if (num < 1 || num > 9 || numbers.contains(num)) {
                    return false;
                }
                numbers.add(num);
            }
        }

        int rowSum1 = 0;
        for (int j = colStart; j < colStart + 3; j++) {
            rowSum1 += grid[rowStart][j];
        }

        int rowSum2 = 0;
        for (int j = colStart; j < colStart + 3; j++) {
            rowSum2 += grid[rowStart + 2][j];
        }

        int colSum1 = 0;
        for (int i = rowStart; i < rowStart + 3; i++) {
            colSum1 += grid[i][colStart];
        }

        int colSum2 = 0;
        for (int i = rowStart; i < rowStart + 3; i++) {
            colSum2 += grid[i][colStart + 2];
        }

        int diagSum1 = 0;
        for (int i = 0; i < 3; i++) {
            diagSum1 += grid[rowStart + i][colStart + i];
        }

        int diagSum2 = 0;
        for (int i = 0; i < 3; i++) {
            diagSum2 += grid[rowStart + i][colStart + 2 - i];
        }

        return (rowSum1 == diagSum1 && rowSum1 == diagSum2 &&
                rowSum1 == colSum1 && rowSum1 == colSum2 &&
                rowSum1 == diagSum1);
    }
}

