public class Solution {
    public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        Map<Integer, Replacement> replacements = new HashMap<>();
        for (int i = 0; i < indices.length; i++) {
            replacements.put(indices[i], new Replacement(sources[i], targets[i]));
        }

        StringBuilder result = new StringBuilder();
        int currentIndex = 0;
        for (int i = 0; i < s.length(); i++) {
            if (replacements.containsKey(currentIndex)) {
                Replacement replacement = replacements.get(currentIndex);
                String source = replacement.source;
                String target = replacement.target;
