                    result.append(s.substring(0, currentIndex));
                    result.append(target);
                    currentIndex += source.length();
                    i = currentIndex - 1;
                } else {
                    result.append(s.charAt(currentIndex));
                }
            } else {
                result.append(s.charAt(currentIndex));
            }
            currentIndex++;
        }

        if (currentIndex < s.length()) {
            result.append(s.substring(currentIndex));
        }

        return result.toString();
    }

    private static class Replacement {
        String source;
        String target;

        public Replacement(String source, String target) {
            this.source = source;
            this.target = target;
        }
