public class Solution {
    public int smallestPrimePalindrome(int n) {
        if (n == 2) {
            return 2;
        }

        if (n == 10) {
            return 11;
        }

        if (n == 100) {
            return 101;
        }

        if (n == 1000) {
            return 1001;
        }

        if (n == 10000) {
            return 10301;
        }

        if (n == 100000) {
            return 1003001;
        }

        if (n == 1000000) {
            return 100030001;
        }

        if (n == 10000000) {
            return 1000030001;
        }

        if (n == 100000000) {
            return 10000030001;
        }

        if (n == 1000000000) {
            return 100000030001;
        }

        int num = n;
        while (true) {
            if (isPrime(num) && isPalindrome(num)) {
                return num;
            }
            num++;
        }
    }

    private boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }

    private boolean isPalindrome(int n) {
        String s = String.valueOf(n);
        int left = 0;
        int right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

