    //       if [0,3] is invalid, next time we will try [1,4],
    //         by adjusting the window to [1,3] first in the current round.
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        int left = 0;
        int maxRobots = 0;
        long windowSum = 0;
        int maxChargeTime = 0;

        for (int right = 0; right < n; right++) {
            windowSum += runningCosts[right];
            maxChargeTime = Math.max(maxChargeTime, chargeTimes[right]);

            while (windowSum + (long)maxChargeTime * (right - left + 1) > budget) {
                windowSum -= runningCosts[left];
                maxChargeTime = 0;
                for (int i = left + 1; i <= right; i++) {
                    maxChargeTime = Math.max(maxChargeTime, chargeTimes[i]);
                }
                left++;
            }

            maxRobots = Math.max(maxRobots, right - left + 1);
        }

        return maxRobots;
    }
}

