public class Solution {
    public long minimumReplacement(int[] nums) {
        long operations = 0;
        long last = nums[nums.length - 1];
        for (int i = nums.length - 2; i >= 0; i--) {
            if (nums[i] <= last) {
                last = nums[i];
            } else {
                long count = (nums[i] + last - 1) / last;
                operations += count - 1;
                last = nums[i] / count;
            }
        }
        return operations;
    }
