public class Solution {
    public int countSpecialNumbers(int n) {
        String s = String.valueOf(n);
        int len = s.length();
        int[][] dp = new int[len + 1][10];
        for (int i = 0; i <= len; i++) {
            for (int j = 0; j < 10; j++) {
                dp[i][j] = -1;
            }
        }
        return solve(0, 0, true, s, dp);
    }

    private int solve(int index, int mask, boolean isLimit, String s, int[][] dp) {
        if (index == s.length()) {
            return 1;
        }
        if (dp[index][mask] != -1) {
            return dp[index][mask];
        }
        int up = isLimit ? s.charAt(index) - '0' : 9;
        int ans = 0;
        for (int i = 0; i <= up; i++) {
            if ((mask & (1 << i)) == 0) {
                ans += solve(index + 1, mask | (1 << i), isLimit && i == up, s, dp);
            }
        }
        dp[index][mask] = ans;
        return ans;
    }
}

