     * Otherwise, it is not a valid name. Return the number of distinct valid names for the company.
     *
     * @param ideas The array of strings representing the list of names.
     * @return The number of distinct valid names for the company.
     */
    public int solve(String[] ideas) {
        Set<String> ideaSet = new HashSet<>();
        for (String idea : ideas) {
            ideaSet.add(idea);
        }

        int count = 0;
        for (int i = 0; i < ideas.length; i++) {
            for (int j = i + 1; j < ideas.length; j++) {
                String ideaA = ideas[i];
                String ideaB = ideas[j];

                String newIdeaA = "" + ideaB.charAt(0) + ideaA.substring(1);
                String newIdeaB = "" + ideaA.charAt(0) + ideaB.substring(1);

                if (!ideaSet.contains(newIdeaA) && !ideaSet.contains(newIdeaB)) {
                    count++;
                }
            }
        }

        return count;
    }
}

