public class Solution {
    public long countSubarrays(int[] nums, long k) {
        long count = 0;
        for (int i = 0; i < nums.length; i++) {
            long sum = 0;
            for (int j = i; j < nums.length; j++) {
                sum += nums[j];
                long score = sum * (j - i + 1);
                if (score < k) {
                    count++;
                }
            }
        }
        return count;
    }
}

