import java.util.Arrays;

public class Solution {
    public int longestIdealString(String s, int k) {
        int[] dp = new int[26];
        Arrays.fill(dp, 0);

        for (char c : s.toCharArray()) {
            int index = c - 'a';
            int maxLen = 0;
            for (int i = 0; i < 26; i++) {
                if (Math.abs(index - i) <= k) {
                    maxLen = Math.max(maxLen, dp[i]);
                }
            }
            dp[index] = maxLen + 1;
        }

        int result = 0;
        for (int len : dp) {
            result = Math.max(result, len);
        }

        return result;
    }
}

