public class Solution {
    public int fillCups(int[] amount) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int a : amount) {
            pq.offer(a);
        }

        int seconds = 0;
        while (pq.size() > 1) {
            int first = pq.poll();
            int second = pq.poll();
            pq.offer(first + second);
            seconds++;
        }

        return seconds;
    }
