public class Solution {
    public boolean validPartition(int[] nums) {
        int n = nums.length;
        if (n == 0) {
            return true;
        }

        boolean[] dp = new boolean[n + 1];
        dp[0] = true;

        for (int i = 1; i <= n; i++) {
            // Check for subarray of length 1
            if (i == 1) {
                dp[i] = false;
            } else {
                // Check for subarray of length 1
                if (dp[i - 1]) {
                    dp[i] = true;
                } else {
                    // Check for subarray of length 2
                    if (i >= 2 && nums[i - 2] == nums[i - 1]) {
                        if (dp[i - 2]) {
                            dp[i] = true;
                        }
                    }
                    // Check for subarray of length 3
                    if (i >= 3 && nums[i - 3] == nums[i - 2] && nums[i - 2] == nums[i - 1]) {
                        if (dp[i - 3]) {
                            dp[i] = true;
                        }
                    }
                    // Check for subarray of length 3 with consecutive increasing elements
                    if (i >= 3 && nums[i - 3] + 1 == nums[i - 2] && nums[i - 2] + 1 == nums[i - 1]) {
                        if (dp[i - 3]) {
                            dp[i] = true;
                        }
                    }
                }
            }

        return dp[n];
    }
}

