import java.util.Arrays;

public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        int[] visited = new int[n];
        Arrays.fill(visited, -1);
        int ans = -1;

        for (int i = 0; i < n; i++) {
            if (visited[i] == -1) {
                int[] path = new int[n];
                int pathLen = 0;
                int curr = i;
                while (curr != -1 && visited[curr] == -1) {
                    visited[curr] = pathLen++;
                    path[pathLen - 1] = curr;
                    curr = edges[curr];
                }

                if (curr != -1 && visited[curr] != -1) {
                    int cycleLen = pathLen - visited[curr];
                    ans = Math.max(ans, cycleLen);
                }
            }
        }

        return ans;
    }
}

