import java.util.Arrays;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        long[] diff = new long[n];
        for (int i = 0; i < n; i++) {
            diff[i] = Math.abs((long)nums1[i] - nums2[i]);
        }

        long[] sortedDiff = Arrays.copyOf(diff, n);
        Arrays.sort(sortedDiff);

        long totalK = k1 + k2;
        long minSum = 0;

        for (int i = 0; i < n; i++) {
            if (totalK > 0) {
                long diffVal = sortedDiff[i];
                if (diffVal == 0) {
                    continue;
                }

                long reduceBy = Math.min(totalK, diffVal);
                minSum += (reduceBy * (reduceBy + 1)) / 2;
                totalK -= reduceBy;
            } else {
                break;
            }
        }

        return minSum;
    }
}

package referenz;


public class Solution {
    public double calculateTax(int[][] brackets, int income) {
        double tax = 0;
        int prevUpper = 0;
        for (int[] bracket : brackets) {
            int upper = bracket[0];
            int percent = bracket[1];
            if (income <= upper) {
                tax += (double) (income - prevUpper) * percent / 100;
                break;
            } else {
                tax += (double) (upper - prevUpper) * percent / 100;
                prevUpper = upper;
            }
        }
        return tax;
    }
}

package referenz;


public class Solution {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;

        for (int i = 0; i < n; i++) {
            if (grid[i][i] == 0) {
                return false;
            }
            if (grid[i][n - 1 - i] == 0) {
                return false;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j || i + j == n - 1) {
                    continue;
                }
                if (grid[i][j] != 0) {
                    return false;
                }
            }
        }

        return true;
    }
}

