                colPos.put(num, -1);
            }
            if (!colPos.containsKey(condition[1])) {
                colPos.put(condition[1], -1);
            }
        }

        // Build row order
        for (int i = 1; i <= k; i++) {
            if (rowPos.containsKey(i)) {
                rowOrder.add(i);
            }
        }

        // Build column order
        for (int i = 1; i <= k; i++) {
            if (colPos.containsKey(i)) {
                colOrder.add(i);
            }
        }

        int rowIdx = 0;
        int colIdx = 0;
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < k; j++) {
                if (rowIdx < k && colIdx < k) {
                    matrix[i][j] = (rowIdx < k && colIdx < k) ? (rowIdx * k + colIdx + 1) : 0;
                    rowIdx++;
                    colIdx++;
                } else {
                    matrix[i][j] = 0;
                }
            }
        }

        return matrix;
    }
}

