        int n = nums.length;
        int maxAnd = 0;
        for (int i = 0; i < n; i++) {
            int currentAnd = nums[i];
            maxAnd = Math.max(maxAnd, currentAnd);
            for (int j = i + 1; j < n; j++) {
                currentAnd &= nums[j];
                maxAnd = Math.max(maxAnd, currentAnd);
            }
        }

        int longest = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                int currentAnd = nums[i];
                for (int k = i + 1; k <= j; k++) {
                    currentAnd &= nums[k];
                }
                if (currentAnd == maxAnd) {
                    longest = Math.max(longest, j - i + 1);
                }
            }
        }
        return longest;
    }
}

