public class Solution {
    public int partitionString(String s) {
        int partitions = 0;
        int start = 0;
        for (int i = 0; i < s.length(); i++) {
            Set<Character> seen = new HashSet<>();
            boolean valid = true;
            for (int j = start; j <= i; j++) {
                char c = s.charAt(j);
                if (seen.contains(c)) {
                    valid = false;
                    break;
                }
                seen.add(c);
            }
            if (!valid) {
                partitions++;
                start = i + 1;
            }
        }
        if (start < s.length()) {
            partitions++;
        }
        return partitions;
    }
}

