        int aliceEndDate = daysInMonth[aliceEndMonth - 1] + aliceEndDay;
        int bobStartDate = daysInMonth[bobStartMonth - 1] + bobStartDay;
        int bobEndDate = daysInMonth[bobEndMonth - 1] + bobEndDay;

        int overlapStart = Math.max(aliceStartDate, bobStartDate);
        int overlapEnd = Math.min(aliceEndDate, bobEndDate);

        if (overlapStart > overlapEnd) {
            return 0;
        }

        return overlapEnd - overlapStart + 1;
    }
}

