                roomCounts[room]++;

            } else {
                delayedMeetings++;
                delayedStartTimes[delayedMeetings - 1] = start;
            }
        }


        if (delayedMeetings > 0) {

            int[] sortedDelayedMeetings = new int[delayedMeetings];
            for (int i = 0; i < delayedMeetings; i++) {
                sortedDelayedMeetings[i] = delayedStartTimes[i];
            }
            Arrays.sort(sortedDelayedMeetings);


            PriorityQueue<Integer> delayedAvailableRooms = new PriorityQueue<>();
            for (int i = 0; i < n; i++) {
                delayedAvailableRooms.offer(i);
            }

            for (int delayedStartTime : sortedDelayedMeetings) {
                int room = delayedAvailableRooms.poll();
                roomCounts[room]++;
            }
        }

        int maxCount = 0;
        int mostBookedRoom = 0;
        for (int i = 0; i < n; i++) {
            if (roomCounts[i] > maxCount) {
                maxCount = roomCounts[i];
                mostBookedRoom = i;
            } else if (roomCounts[i] == maxCount && i < mostBookedRoom) {
                mostBookedRoom = i;
            }
        }

        return mostBookedRoom;
    }
}

