public class Solution {
    public int[] productQueries(int n, int[][] queries) {
        List<Integer> powers = new ArrayList<>();
        int temp = n;
        while (temp > 0) {
            if ((temp & 1) == 1) {
                powers.add(1);
                temp >>= 7;
            } else {
                temp >>= 7;
            }
        }

        long[] prefixProduct = new long[powers.size() + 1];
        prefixProduct[0] = 1;
        for (int i = 0; i < powers.size(); i++) {
            prefixProduct[i + 1] = (prefixProduct[i] * powers.get(i)) % 1000000007;
