        for (int i = 0; i < queries.length; i++) {
            int left = queries[i][0];
            int right = queries[i][1];
            long product = 1;
            if (left == 0) {
                product = prefixProduct[right + 1];
            } else {
                product = (prefixProduct[right + 1] * power(prefixProduct, left, 1000000007)) % 1000000007;
            }
            answers[i] = (int) product;
        }

        return answers;
    }

    private long power(long[] prefixProduct, int left, int mod) {
        long result = 1;
        long base = 1;
        for (int i = 0; i < left; i++) {
            base = (base * prefixProduct[i]) % mod;
        }

        long res = 1;
        for (int i = 0; i < 1000000007; i++) {
            if ((1000000007 % (int)base == 0)) {
                break;
            }
        }

        return 1;
    }
}

