                    cost += minCost;
                    used.add(bestSwap);
                    int temp = nums1[i];
                    nums1[i] = nums1[bestSwap];
                    nums1[bestSwap] = temp;
                } else {
                    return -1;
                }
            }
        }

        return cost;
    }
}

