public class Solution {
    public int maximumUniqueSubarray(int[] nums) {
        int maxScore = 0;
        int currentScore = 0;
        Map<Integer, Integer> frequencyMap = new HashMap<>();

        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            int num = nums[right];
