import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        int[] ans = new int[n - 1];
        for (int d = 1; d < n; d++) {
            int count = 0;
            for (int i = 0; i < (1 << n); i++) {
                List<Integer> subtree = new ArrayList<>();
                for (int j = 0; j < n; j++) {
                    if ((i >> j) % 2 == 1) {
                        subtree.add(j + 1);
                    }
                }

                if (subtree.isEmpty()) continue;

                boolean isSubtree = true;
                for (int u = 0; u < subtree.size(); u++) {
                    for (int v = u + 1; v < subtree.size(); v++) {
                        if (!isConnected(subtree.get(u), subtree.get(v), subtree, adj)) {
                            isSubtree = false;
                            break;
                        }
                    }
                    if (!isSubtree) break;
                }

                if (isSubtree) {
                    int maxDist = 0;
                    for (int u = 0; u < subtree.size(); u++) {
                        for (int v = u + 1; v < subtree.size(); v++) {
                            maxDist = Math.max(maxDist, distance(subtree.get(u), subtree.get(v), subtree, adj));
                        }
                    }
                    if (maxDist == d) {
                        count++;
                    }
                }
            }
            ans[d - 1] = count;
        }
        return ans;
    }

    private boolean isConnected(int start, int end, List<Integer> subtree, List<List<Integer>> adj) {
        if (start == end) return true;

        boolean[] visited = new boolean[subtree.size()];
        List<Integer> q = new ArrayList<>();
        q.add(0);
        visited[0] = true;

        int head = 0;
        while (head < q.size()) {
            int uIndex = q.get(head++);
            int u = subtree.get(uIndex);

            for (int v : adj.get(u)) {
                if (subtree.contains(v) && !visited[subtree.indexOf(v)]) {
                    if (v == end) return true;
                    visited[subtree.indexOf(v)] = true;
                    q.add(subtree.indexOf(v));
                }
            }
        }
        return false;
    }

    private int distance(int start, int end, List<Integer> subtree, List<List<Integer>> adj) {
        if (start == end) return 0;

        boolean[] visited = new boolean[subtree.size()];
        int[] dist = new int[subtree.size()];
        List<Integer> q = new ArrayList<>();
        q.add(subtree.indexOf(start));
        visited[subtree.indexOf(start)] = true;
        dist[subtree.indexOf(start)] = 0;

        int head = 0;
        while (head < q.size()) {
            int uIndex = q.get(head++);
            int u = subtree.get(uIndex);

            for (int v : adj.get(u)) {
                if (subtree.contains(v) && !visited[subtree.indexOf(v)]) {
                    visited[subtree.indexOf(v)] = true;
                    dist[subtree.indexOf(v)] = dist[uIndex] + 1;
                    q.add(subtree.indexOf(v));
                }
            }
        }

        return dist[subtree.indexOf(end)];
    }
}

