    public class Solution {
        int[] parent;

        public Dsu(int n) {
            parent = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
            }
        }

        public int find(int num) {
            if (parent[num] == num) {
                return num;
            }
            return parent[num] = find(parent[num]);
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                parent[rootX] = rootY;
            }
        }
    }

    public boolean[] canReach(int n, int[][] edgeList, int[][] queries) {
        Dsu dsu = new Dsu(n);
        for (int[] edge : edgeList) {
            int u = edge[0];
            int v = edge[1];
            int dis = edge[2];
            if (dis < 100000) {
                dsu.union(u, v);
            }
        }

        boolean[] answer = new boolean[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int p = queries[i][0];
            int q = queries[i][1];
            int limit = queries[i][2];

            Dsu tempDsu = new Dsu(n);
            for (int[] edge : edgeList) {
                int u = edge[0];
                int v = edge[1];
                int dis = edge[2];
                if (dis < limit) {
                    tempDsu.union(u, v);
                }
            }

            answer[i] = tempDsu.find(p) == tempDsu.find(q);
        }

        return answer;
    }
}

