import java.util.LinkedList;

public class Solution {
    public int minimumOneBitOperations(int n) {
        if (n == 0) {
            return 0;
        }

        int[] dp = new int[n + 1];
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            dp[i] = Integer.MAX_VALUE;
            for (int j = 0; j < 32; j++) {
                if ((i >> j) & 1 == 1) {
                    int prev = i ^ (1 << j);
                    if (prev >= 0) {
                        if (prev == 0) {
                            dp[i] = Math.min(dp[i], 1);
                        } else {
                            dp[i] = Math.min(dp[i], dp[prev] + 1);
                        }
                    }
                }
            }
            if (dp[i] == Integer.MAX_VALUE) {
                dp[i] = 1;
            }
        }

        return dp[n];
    }
}

