public class Solution {
    public int minOperations(int[] nums, int x) {
        int n = nums.length;
        int target = x;
        int minOps = Integer.MAX_VALUE;

        for (int i = 0; i < (1 << n); i++) {
            int currentX = x;
            int ops = 0;
            int[] currentNums = nums.clone();

            for (int j = 0; j < n; j++) {
                if ((i >> j) % 2 == 0) {
                    // Remove from left
                    currentX -= currentNums[0];
                    currentNums = java.util.Arrays.copyOfRange(currentNums, 1, currentNums.length);
                } else {
                    // Remove from right
                    currentX -= currentNums[currentNums.length - 1];
                    currentNums = java.util.Arrays.copyOfRange(currentNums, 0, currentNums.length - 1);
                }
                ops++;
            }

            if (currentX == 0) {
                minOps = Math.min(minOps, ops);
            }
        }

        if (minOps == Integer.MAX_VALUE) {
            return -1;
        }

        return minOps;
    }
}

