public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        long profit = 0;
        int n = inventory.length;
        long MOD = 1000000007;

        int i = n - 1;
        long ballsSold = 0;

        while (orders > 0) {
            if (i < 0) {
                break;
            }

            long ballsCanSell = inventory[i];

            if (ballsCanSell == 0) {
                i--;
                continue;
            }

            long sell = Math.min(ballsCanSell, (long)orders);
            long price = inventory[i];

            profit = (profit + (price * sell) - (price - 1) * (sell / 2));
            profit %= MOD;

            orders -= sell;
            inventory[i] -= sell;
        }

        return (int)profit;
    }
}

