        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int[] road : roads) {
            int u = road[0] - 1;
            int v = road[1] - 1;
            adj[u].add(v);
            adj[v].add(u);
        }

        int maxRank = 0;
        for (int i = 0; i < n; i++) {
