public class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = stickers.length;
        HashMap<String, int[]> stickerCounts = new HashMap<>();

        for (String sticker : stickers) {
            int[] counts = new int[26];
            for (char c : sticker.toCharArray()) {
                counts[c - 'a']++;
            }
            stickerCounts.put(sticker, counts);
        }

        int[] targetCounts = new int[26];
        for (char c : target.toCharArray()) {
            targetCounts[c - 'a']++;
        }

        int[] dp = new int[target.length() + 1];
        for (int i = 1; i <= target.length(); i++) {
            dp[i] = Integer.MAX_VALUE;
        }

        for (int i = 1; i <= target.length(); i++) {
            for (String sticker : stickers) {
                int[] stickerCount = stickerCounts.get(sticker);
                boolean possible = true;
                int[] needed = new int[26];
                for (int j = 0; j < 26; j++) {
                    needed[j] = Math.max(0, targetCounts[j] - targetCounts[j]);
                    if (needed[j] > stickerCount[j]) {
                        possible = false;
                        break;
                    }
                }
                if (possible) {
                    dp[i] = Math.min(dp[i], dp[i - 1] + 1);
                }
            }
        }

        if (dp[target.length()] == Integer.MAX_VALUE) {
            return -1;
        }

        return dp[target.length()];
    }
}

