                    double sum = sums[i] + sums[j - i] + sums[l - j];
                    if (sum > maxSum) {
                        maxSum = sum;
                        result[0] = i;
                        result[1] = j;
                        result[2] = l;
                    } else if (sum == maxSum) {
                        if (i < result[0] || (i == result[0] && j < result[1]) || (i == result[0] && j == result[1] && l < result[2])) {
                            result[0] = i;
                            result[1] = j;
                            result[2] = l;
                        }
                    }
                }
            }
        }

