            int right = left + side;

            int currentHeight = 0;
            for (Integer height : heights) {
                if (height >= left && height < right) {
                    currentHeight = Math.max(currentHeight, height);
                }
            }

            int newHeight = currentHeight + side;

            Integer floor = heights.floor(newHeight);
            if (floor == null) {
                heights.add(newHeight);
            } else {
                int insertHeight = newHeight;
                if (floor < newHeight) {
                    heights.add(newHeight);
                }
            }

            int newMaxHeight = 0;
            for (Integer height : heights) {
                newMaxHeight = Math.max(newMaxHeight, height);
            }
            maxHeight = newMaxHeight;
            ans.add(maxHeight);
        }

        return ans;
    }
}

