public class Solution {
    public int flipLights(int n, int m) {
        if (n == 0) {
            return 1;
        }

        if (m == 0) {
            return 1;
        }

        int[] dp = new int[m + 1];
        dp[0] = 1;

        for (int i = 1; i <= m; i++) {
            dp[i] = dp[i - 1] * 3;
            if (i >= 2) {
                dp[i] -= dp[i - 2] * 2;
            }
            dp[i] %= 1000000007;
            if (dp[i] < 0) {
                dp[i] += 1000000007;
            }
        }

        return dp[m];
    }
}

