public class Solution {
    public String solveEquation(String equation) {
        int xCoefficient = 0;
        int constant = 0;

        String[] parts = equation.split("=");
        if (parts.length != 2) {
            return "No solution";
        }

        String leftSide = parts[0];
        String rightSide = parts[1];

        int[] leftCoefficients = parseSide(leftSide);
        int[] rightCoefficients = parseSide(rightSide);

        xCoefficient = leftCoefficients[0] - rightCoefficients[0];
        constant = rightCoefficients[1] - leftCoefficients[1];

        if (xCoefficient == 0) {
            if (constant == 0) {
                return "Infinite solutions";
            } else {
                return "No solution";
            }
        }

        return "x=" + (constant / xCoefficient);
    }

    private int[] parseSide(String side) {
        int xCoefficient = 0;
        int constant = 0;

        String[] terms = side.split("(?=[+-])");
        for (String term : terms) {
            term = term.trim();
            if (term.isEmpty()) continue;

            if (term.contains("+") || term.contains("-")) {
                String[] subTerms = term.split("(?=[+-])");
                for (String subTerm : subTerms) {
                    subTerm = subTerm.trim();
                    if (subTerm.isEmpty()) continue;

                    if (subTerm.contains("x")) {
                        String coeffStr = "";
                        if (subTerm.startsWith("+")) {
                            coeffStr = subTerm.substring(1);
                        } else if (subTerm.startsWith("-")) {
                            coeffStr = "-" + subTerm.substring(1);
                        } else {
                            coeffStr = subTerm;
                        }
                        int coeff = coeffStr.isEmpty() ? 1 : Integer.parseInt(coeffStr);
                        xCoefficient += coeff;
                    } else {
                        int num = Integer.parseInt(subTerm);
                        constant += num;
                    }
                }
            } else {
                if (term.contains("x")) {
                    String coeffStr = "";
                    if (term.startsWith("+")) {
                        coeffStr = term.substring(1);
                    } else if (term.startsWith("-")) {
                        coeffStr = "-" + term.substring(1);
                    } else {
                        coeffStr = term;
                    }
                    int coeff = coeffStr.isEmpty() ? 1 : Integer.parseInt(coeffStr);
                    xCoefficient += coeff;
                } else {
                    constant += Integer.parseInt(term);
                }
            }
        }

        return new int[]{xCoefficient, constant};
    }

    private int xCoefficient = 0;
}

