public class Solution {
    public List<Double> averageOfLevels(TreeNode root) {
        List<Double> averages = new ArrayList<>();
        Map<Integer, List<Integer>> levelMap = new HashMap<>();
        bfs(root, 0, levelMap);

        for (int level : levelMap.keySet()) {
            List<Integer> values = levelMap.get(level);
            double sum = 0;
            for (int value : values) {
                sum += value;
            }
            averages.add(sum / values.size());
        }

        return averages;
    }

    private void bfs(TreeNode node, int level, Map<Integer, List<Integer>> levelMap) {
        if (node == null) {
            return;
        }

        if (!levelMap.containsKey(level)) {
            levelMap.put(level, new ArrayList<>());
        }
        levelMap.get(level).add(node.val);

        bfs(node.left, level + 1, levelMap);
        bfs(node.right, level + 1, levelMap);
    }
}

