    public int shortestSubarray(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }

        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int num : nums) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        int degree = 0;
        for (int frequency : frequencyMap.values()) {
            degree = Math.max(degree, frequency);
        }

        int minLength = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i; j < nums.length; j++) {
                Map<Integer, Integer> subarrayFrequencyMap = new HashMap<>();
                for (int k = i; k <= j; k++) {
                    subarrayFrequencyMap.put(nums[k], subarrayFrequencyMap.getOrDefault(nums[k], 0) + 1);
                }

                int subarrayDegree = 0;
                for (int frequency : subarrayFrequencyMap.values()) {
                    subarrayDegree = Math.max(subarrayDegree, frequency);
                }

                if (subarrayDegree == degree) {
                    minLength = Math.min(minLength, j - i + 1);
                }
            }
        }

        return minLength;
    }
}

