public class Solution {
    public int[][] imageSmoother(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] smoothedMatrix = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int sum = 0;
                int count = 0;

                for (int x = Math.max(0, i - 1); x <= Math.min(m - 1, i + 1); x++) {
                    for (int y = Math.max(0, j - 1); y <= Math.min(n - 1, j + 1); y++) {
                        sum += matrix[x][y];
                        count++;
                    }
                }

                smoothedMatrix[i][j] = sum / count;
            }
        }

        return smoothedMatrix;
    }
}

