    }

    private int dfs(TreeNode node) {
        if (node == null) {
            return 0;
        }

        int leftLen = dfs(node.left);
        int rightLen = dfs(node.right);

        int currentLen = 1;
        int leftPath = 0;
        int rightPath = 0;

        if (node.left != null && node.left.val == node.val) {
            leftPath = leftPathHelper(node.left);
        }
        if (node.right != null && node.right.val == node.val) {
            rightPath = rightPathHelper(node.right);
        }

        maxLen = Math.max(maxLen, leftPath + rightPath);

        return Math.max(leftPath, rightPath) + 1;
    }

    private int leftPathHelper(TreeNode node) {
        if (node == null) {
            return 0;
        }
        if (node.left == null && node.right == null) {
            return 1;
        }

        int left = 0;
        if (node.left != null && node.left.val == node.val) {
            left = leftPathHelper(node.left);
        }
        int right = 0;
        if (node.right != null && node.right.val == node.val) {
            right = leftPathHelper(node.right);
        }

        return Math.max(left, right) + 1;
    }

    private int rightPathHelper(TreeNode node) {
        if (node == null) {
            return 0;
        }
        if (node.left == null && node.right == null) {
            return 1;
        }

        int left = 0;
        if (node.left != null && node.left.val == node.val) {
            left = rightPathHelper(node.left);
        }
        int right = 0;
        if (node.right != null && node.right.val == node.val) {
            right = rightPathHelper(node.right);
        }

        return Math.max(left, right) + 1;
    }
