public class Solution {
    public TreeNode addOneRow(TreeNode root, int val, int depth) {
        if (depth == 1) {
            TreeNode newRoot = new TreeNode(val);
            newRoot.left = root;
            return newRoot;
        }

        return addOneRowHelper(root, val, depth, 1);
    }

    private TreeNode addOneRowHelper(TreeNode root, int val, int depth, int currentDepth) {
        if (root == null) {
            return null;
        }

        if (currentDepth == depth) {
            TreeNode newNode = new TreeNode(val);
            newNode.left = root.left;
            root.left = newNode;
            return root;
        }

        addOneRowHelper(root.right, val, depth, currentDepth + 1);
        addOneRowHelper(root.left, val, depth, currentDepth + 1);

        return root;
    }
}

