        });

        for (Map.Entry<String, Integer> entry : counts.entrySet()) {
            freqMap.put(new Pair(entry.getKey(), entry.getValue()), entry.getKey());
        }

        List<String> result = new ArrayList<>();
        int i = 0;
        for (String word : freqMap.values()) {
            if (i < k) {
                result.add(word);
                i++;
            } else {
                break;
            }
        }

        return result;
    }

    private static class Pair {
        String word;
        int freq;

        public Pair(String word, int freq) {
            this.word = word;
            this.freq = freq;
        }
    }
}

