public class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        if (preorder == null || inorder == null || preorder.length == 0 || inorder.length == 0) {
            return null;
        }

        Map<Integer, Integer> inorderIndexMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderIndexMap.put(inorder[i], i);
        }

        return buildTreeHelper(preorder, inorder, inorderIndexMap, 0, inorder.length - 1, 0);
    }

    private TreeNode buildTreeHelper(int[] preorder, int[] inorder, Map<Integer, Integer> inorderIndexMap, int inorderStart, int inorderEnd, int preorderIndex) {
        if (preorderIndex >= preorder.length || inorderStart > inorderEnd) {
            return null;
        }

        int rootValue = preorder[preorderIndex];
        TreeNode root = new TreeNode(rootValue);

        int inorderIndex = inorderIndexMap.get(rootValue);

        root.left = buildTreeHelper(preorder, inorder, inorderIndexMap, inorderStart, inorderIndex - 1, preorderIndex + 1);
        root.right = buildTreeHelper(preorder, inorder, inorderIndexMap, inorderIndex + 1, inorderEnd, preorderIndex + 1 + (inorderIndex - inorderStart));

        return root;
    }
}

