        for (int i = 0; i < n; i++) {
            int move1 = 0;
            int move2 = 0;

            if (i % 2 == 0) {
                if (i > 0 && nums[i] >= nums[i - 1]) {
                    move1 = nums[i] - nums[i - 1] + 1;
                }
                if (i < n - 1 && nums[i] >= nums[i + 1]) {
                    move1 = nums[i] - nums[i + 1] + 1;
                }
            } else {
                if (i > 0 && nums[i] >= nums[i - 1]) {
                    move1 = nums[i] - nums[i - 1] + 1;
                }
                if (i < n - 1 && nums[i] >= nums[i + 1]) {
                    move1 = nums[i] - nums[i + 1] + 1;
                }
            }

            if (i % 2 != 0) {
                if (i > 0 && nums[i] >= nums[i - 1]) {
                    move2 = nums[i] - nums[i - 1] + 1;
                }
                if (i < n - 1 && nums[i] >= nums[i + 1]) {
                    move2 = nums[i] - nums[i + 1] + 1;
                }
            } else {
                if (i > 0 && nums[i] >= nums[i - 1]) {
                    move2 = nums[i] - nums[i - 1] + 1;
                }
                if (i < n - 1 && nums[i] >= nums[i + 1]) {
                    move2 = nums[i] - nums[i + 1] + 1;
                }
            }

            moves1[i] = move1;
            moves2[i] = move2;
        }

        int sum1 = 0;
        for (int move : moves1) {
            sum1 += move;
        }
        int sum2 = 0;
        for (int move : moves2) {
