public class Solution {
    public List<String> findInvalidTransactions(List<String> transactions) {
        List<String> invalidTransactions = new ArrayList<>();
        Map<String, List<Transaction>> transactionsByNameAndCity = new HashMap<>();

        for (String transactionStr : transactions) {
            String[] parts = transactionStr.split(",");
            String name = parts[0];
            int time = Integer.parseInt(parts[1]);
            double amount = Double.parseDouble(parts[2]);
            String city = parts[3];

            Transaction transaction = new Transaction(name, time, amount, city);

            transactionsByNameAndCity.computeIfAbsent(name, k -> new ArrayList<>()).add(transaction);
        }

        for (String name : transactionsByNameAndCity.keySet()) {
            List<Transaction> transactionList = transactionsByNameAndCity.get(name);
            for (int i = 0; i < transactionList.size(); i++) {
                Transaction currentTransaction = transactionList.get(i);
                if (currentTransaction.amount > 1000) {
                    invalidTransactions.add(currentTransaction.getTransactionString());
                } else {
                    for (int j = 0; j < transactionList.size(); j++) {
                        if (i != j) {
                            Transaction otherTransaction = transactionList.get(j);
                            if (otherTransaction.city != currentTransaction.city &&
                                    Math.abs(currentTransaction.time - otherTransaction.time) <= 60) {
                                invalidTransactions.add(currentTransaction.getTransactionString());
                                break;
                            }
                        }
                    }
                }
            }
        }

        return invalidTransactions;
    }

    private static class Transaction {
        String name;
        int time;
        double amount;
        String city;

        public Transaction(String name, int time, double amount, String city) {
            this.name = name;
            this.time = time;
            this.amount = amount;
            this.city = city;
        }

        public String getTransactionString() {
