            while (curr[0] < next[0]) {
                path.append('D');
                curr[0]++;
            }
            while (curr[1] < next[1]) {
                path.append('R');
                curr[1]++;
            }
            path.append('!');
            curr = next;
        }

        return path.toString();
    }
}

