        PriorityQueue<Double> pq = new PriorityQueue<>();
        for (double time : timeToReach) {
            pq.offer(time);
        }

        int eliminated = 0;
        int currentTime = 0;
        while (!pq.isEmpty()) {
            double time = pq.poll();
            if (time > currentTime) {
                eliminated++;
                currentTime = time + 1;
            } else {
                break;
            }
        }

        return eliminated;
    }
}

