public class Solution {
    public long numberOfWeeks(int[] milestones) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int milestone : milestones) {
            pq.offer(milestone);
        }

        long weeks = 0;
        int consecutive = 0;

        while (!pq.isEmpty()) {
            int currentMilestone = pq.poll();

            if (consecutive == 0) {
                weeks++;
                consecutive = 0;
            } else {
                if (currentMilestone > 0) {
                    weeks++;
                    consecutive = 0;
                } else {
                    weeks++;
                    consecutive = 0;
                }
            }

            if (!pq.isEmpty()) {
                int nextMilestone = pq.peek();
                if (nextMilestone > 0) {
                    consecutive++;
                }
            }
        }

        return weeks;
    }
}

