public class Solution {
    public long minimumPerimeter(long neededApples) {
        long low = 0;
        long high = (long) Math.sqrt(neededApples);
        long ans = high;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            long sum = 0;
            for (int i = -mid; i <= mid; i++) {
                for (int j = -mid; j <= mid; j++) {
                    sum += Math.abs(i) + Math.abs(j);
                }
            }

            if (sum >= neededApples) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        return (long) ans * 4;
    }
}

