public class Solution {
    public int smallestChair(int[][] times, int targetFriend) {
        int n = times.length;
        Arrays.sort(times, (a, b) -> a[0] - b[0]);

        PriorityQueue<Integer> chairs = new PriorityQueue<>();
        int currentChair = 0;

        for (int i = 0; i < n; i++) {
            if (!chairs.isEmpty() && chairs.peek() <= times[i][0]) {
                chairs.poll();
            }

            if (i == targetFriend) {
                return currentChair;
            }

            if (chairs.isEmpty()) {
                currentChair++;
            } else {
                currentChair = chairs.peek();
                chairs.poll();
            }
            chairs.offer(currentChair);
        }

        return currentChair;
    }
}

