                }
            }
        }

        // Check diagonal lines (top-left to bottom-right)
        for (int i = 0; i < 8; i++) {
            int r = rMove - i;
            int c = cMove - i;
            if (r >= 0 && r < 8 && c >= 0 && c < 8) {
                if (board[r][c] == opponent && board[r + 1][c + 1] == color && board[r + 2][c + 2] == color) {
