public class Solution {
    public int countSubIslands(int[][] grid1, int[][] grid2) {
        int m = grid1.length;
        int n = grid1[0].length;
        int count = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid2[i][j] == 1) {
                    if (isSubIsland(grid1, grid2, i, j, m, n)) {
                        count++;
                    }
                }
            }
        }

        return count;
    }

    private boolean isSubIsland(int[][] grid1, int[][] grid2, int row, int col, int m, int n) {
        if (row < 0 || row >= m || col < 0 || col >= n || grid2[row][col] == 0) {
            return true;
        }

        grid2[row][col] = 0;

        boolean up = isSubIsland(grid1, grid2, row - 1, col, m, n);
        boolean down = isSubIsland(grid1, grid2, row + 1, col, m, n);
        boolean left = isSubIsland(grid1, grid2, row, col - 1, m, n);
        boolean right = isSubIsland(grid1, grid2, row, col + 1, m, n);

        return up && down && left && right;
    }
}

