public class Solution {
    public int minimizeTheDifference(int[][] mat, int target) {
        int n = mat.length;
        int[][] dp = new int[n + 1][100001];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
