                        if (nextSum >= 0 && nextSum <= 100000) {
                            dp[i][nextSum] = Math.min(dp[i][nextSum], dp[i - 1][j] + 1);
                        }
                    }
                }
            }
        }

        int minDiff = Integer.MAX_VALUE;
        for (int j = 0; j <= 100000; j++) {
            if (dp[n][j] != Integer.MAX_VALUE) {
                minDiff = Math.min(minDiff, Math.abs(target - j));
            }
        }

        return minDiff;
    }
