import java.util.ArrayList;
import java.util.List;
public class Solution {
    public int[][] findFarmland(int[][] land) {
        if (land == null || land.length == 0) {
            return new int[0][];
        }

        int m = land.length;
        int n = land[0].length;
        List<int[]> groups = new ArrayList<>();
        boolean[][] visited = new boolean[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (land[i][j] == 1 && !visited[i][j]) {
                    int r1 = i;
                    int c1 = j;
                    int r2 = i;
                    int c2 = j;

                    // Find the bottom right corner of the group
                    while (r2 + 1 < m && land[r2 + 1][j] == 1) {
                        r2++;
                    }
                    while (c2 + 1 < n && land[i][c2 + 1] == 1) {
                        c2++;
                    }

                    // Verify that the group is rectangular
                    boolean isRectangular = true;
                    for (int r = i; r <= r2; r++) {
                        for (int c = j; c <= c2; c++) {
                            if (land[r][c] != 1) {
                                isRectangular = false;
                                break;
                            }
                        }
                        if (!isRectangular) break;
                    }

                    if (isRectangular) {
                        groups.add(new int[]{r1, c1, r2, c2});
                    }

                    // Mark the group as visited
                    for (int r = i; r <= r2; r++) {
                        for (int c = j; c <= c2; c++) {
                            visited[r][c] = true;
                        }
                    }
                }
            }
        }

        return groups.toArray(new int[0][]);
    }
}

