public class Solution {
    public List<List<Long>> splitPainting(int[][] segments) {
        TreeMap<Integer, Long> map = new TreeMap<>();
        for (int[] segment : segments) {
            int start = segment[0];
            int end = segment[1];
            long color = segment[2];
            map.put(start, (long)map.getOrDefault(start, 0L) + color);
            map.put(end, (long)map.getOrDefault(end, 0L) - color);
        }

        List<List<Long>> painting = new ArrayList<>();
        long currentSum = 0;
        Integer prev = null;

        for (Integer pos : map.keySet()) {
            if (prev != null) {
                if (currentSum > 0) {
                    painting.add(List.of((long)prev, (long)pos, currentSum));
                }
            }
            currentSum += map.get(pos);
            prev = pos;
        }

        return painting;
    }
}

