public class Solution {
    public TreeNode canMerge(List<TreeNode> trees) {
        if (trees == null || trees.size() == 0) {
            return null;
        }

        if (trees.size() == 1) {
            return trees.get(0);
        }

        Map<Integer, TreeNode> rootToNode = new HashMap<>();
        for (TreeNode tree : trees) {
            rootToNode.put(tree.val, tree);
        }

        TreeNode root = null;
        if (trees.size() > 0) {
            root = trees.get(0);
        }

        if (trees.size() == 2) {
            if (findLeafValue(trees.get(0), trees.get(1).val)) {
                return trees.get(1);
            }
            if (findLeafValue(trees.get(1), trees.get(0).val)) {
                return trees.get(0);
            }
            return null;
        }

        return null;
    }

    private boolean findLeafValue(TreeNode root, int target) {
        if (root == null) {
            return false;
        }

        if (root.left == null && root.right == null) {
            return root.val == target;
        }

        return findLeafValue(root.left, target) || findLeafValue(root.right, target);
    }
}

