import java.util.HashMap;
import java.util.Map;

public class Solution {
    private static final int MOD = 1000000007;

    public int colorTheGrid(int m, int n) {
        if (m == 0 || n == 0) {
            return 0;
        }

        if (m == 1) {
            return 3 * 2;
        }

        if (n == 1) {
            return 3 * 2;
        }

        long[][] dp = new long[m][1 << 3];
        for (int i = 0; i < m; i++) {
            for (int mask = 0; mask < (1 << 3); mask++) {
                dp[i][mask] = 0;
            }
        }

        for (int mask = 0; mask < (1 << 3); mask++) {
            dp[0][mask] = 1;
        }

        for (int i = 1; i < m; i++) {
            for (int mask = 0; mask < (1 << 3); mask++) {
                for (int prevMask = 0; prevMask < (1 << 3); prevMask++) {
                    if (isValid(mask, prevMask)) {
                        dp[i][mask] = (dp[i][mask] + dp[i - 1][prevMask]) % MOD;
                    }
                }
            }
        }

        long result = 0;
        for (int mask = 0; mask < (1 << 3); mask++) {
            result = (result + dp[m - 1][mask]) % MOD;
        }

        return (int) result;
    }

    private boolean isValid(int mask, int prevMask) {
        for (int i = 0; i < 3; i++) {
            if ((mask & (1 << i)) != ((prevMask & (1 << i)))) {
                if (i > 0 && (mask & (1 << i)) == (mask & (1 << (i - 1)))) {
                    return false;
                }
                if (i < 2 && (mask & (1 << i)) == (mask & (1 << (i + 1)))) {
                    return false;
                }
            }
        }
        return true;
    }
}

