public class Solution {
    public int minSpaceWastedKResizing(int[] arr, int k) {
        int n = arr.length;
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + arr[i];
        }

        long[][] dp = new long[n][k + 1];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], Long.MAX_VALUE);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= k; j++) {
                if (j == 0) {
                    dp[i][j] = (long) arr[i] - arr[i];
                } else {
                    for (int m = 0; m <= i; m++) {
                        long size = prefixSum[i + 1] - prefixSum[m];
                        if (size >= prefixSum[i + 1] - prefixSum[m]) {
                            dp[i][j] = Math.min(dp[i][j], dp[m][j - 1] + size - (prefixSum[i + 1] - prefixSum[m]));
                        }
                    }
                }
            }

        long minWasted = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            minWasted = Math.min(minWasted, dp[i][k]);
        }

        return (int) minWasted;
    }
}

