public class Solution {
    public long maxPoints(int[][] points) {
        int m = points.length;
        int n = points[0].length;

        long[][] dp = new long[m][n];

        for (int j = 0; j < n; j++) {
            dp[0][j] = points[0][j];
        }

        for (int i = 1; i < m; i++) {
            for (int j = 0; j < n; j++) {
                long maxScore = Long.MIN_VALUE;
                for (int k = 0; k < n; k++) {
                    maxScore = Math.max(maxScore, dp[i - 1][k] + points[i][j] - Math.abs(k - j));
                }
                dp[i][j] = maxScore;
            }
        }

        long maxTotal = Long.MIN_VALUE;
        for (int j = 0; j < n; j++) {
            maxTotal = Math.max(maxTotal, dp[m - 1][j]);
        }

        return maxTotal;
    }
}

