import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    private static final int MOD = 1000000007;

    public int numberOfGoodSubsets(int[] nums) {
        int n = nums.length;
        List<Integer> primes = new ArrayList<>();
        Set<Integer> nonPrimes = new HashSet<>();

        for (int num : nums) {
            if (isPrime(num)) {
                primes.add(num);
            } else {
                nonPrimes.add(num);
            }
        }

        long ans = 0;
        long powerOfTwo = 1;

        for (int prime : primes) {
            powerOfTwo = (powerOfTwo * 2) % MOD;
        }

        if (nonPrimes.isEmpty()) {
            ans = powerOfTwo;
        } else {
            long count = 0;
            for (int i = 0; i < (1 << n); i++) {
                List<Integer> subset = new ArrayList<>();
                for (int j = 0; j < n; j++) {
                    if ((i >> j) % 2 == 1) {
                        subset.add(nums[j]);
                    }
                }

                if (isGoodSubset(subset)) {
                    count++;
                }
            }
            ans = count;
        }

        return (int) ans;
    }

    private boolean isPrime(int n) {
        if (n <= 1) return false;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) return false;
        }
        return true;
    }

    private boolean isGoodSubset(List<Integer> subset) {
        long product = 1;
        for (int num : subset) {
            product *= num;
        }

        if (product == 0) return false;

        if (product == 1) return false;

        Set<Integer> distinctPrimes = new HashSet<>();
        int temp = product;
        for (int i = 2; i * i <= temp; i++) {
            while (temp % i == 0) {
                if (isPrime(i)) {
                    distinctPrimes.add(i);
                }
                temp /= i;
            }
        }
        if (temp > 1) {
            if (isPrime(temp)) {
                distinctPrimes.add(temp);
            }
        }

        return !distinctPrimes.isEmpty();
    }
}

