import java.util.Arrays;

public class Solution {
    public int latestDayToCross(int row, int col, int[][] cells) {
        int n = cells.length;
        int[][] grid = new int[row + 1][col + 1];
        for (int i = 1; i <= row; i++) {
            Arrays.fill(grid[i], 1);
        }

        for (int i = 0; i < n; i++) {
            grid[cells[i][0]][cells[i][1]] = 0;
        }

        int left = 0;
        int right = n;
        int ans = 0;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            int[][] tempGrid = new int[row + 1][col + 1];
            for (int i = 1; i <= row; i++) {
                Arrays.fill(tempGrid[i], 1);
            }
            for (int i = 0; i < mid; i++) {
                tempGrid[cells[i][0]][cells[i][1]] = 0;
            }

            if (canCross(row, col, tempGrid)) {
                ans = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return ans;
    }

    private boolean canCross(int row, int col, int[][] grid) {
        boolean[][] visited = new boolean[row + 1][col + 1];
        return dfs(1, 1, row, col, grid, visited);
    }

    private boolean dfs(int r, int c, int row, int col, int[][] grid, boolean[][] visited) {
        if (r == row) {
            return true;
        }

        visited[r][c] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (nr >= 1 && nr <= row && nc >= 1 && nc <= col && grid[nr][nc] == 1 && !visited[nr][nc]) {
                if (dfs(nr, nc, row, col, grid, visited)) {
                    return true;
                }
            }
        }

        return false;
    }
}

