import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public List<List<String>> deleteDuplicateFolder(List<List<String>> paths) {
        Map<String, List<String>> map = new HashMap<>();
        for (List<String> path : paths) {
            String key = String.join("/", path);
            map.put(key, path);
        }

        List<List<String>> result = new ArrayList<>();
        for (List<String> path : paths) {
            String key = String.join("/", path);
            if (!isMarked.get(key)) {
                result.add(path);
            }
        }

        return result;
    }

    private static Map<String, Boolean> isMarked = new HashMap<>();

    public static void markIdentical(List<List<String>> paths, String key) {
        isMarked.put(key, true);
        for (List<String> path : paths) {
            String currentKey = String.join("/", path);
            if (currentKey.startsWith(key) && !isMarked.containsKey(currentKey)) {
                markIdentical(paths, currentKey);
            }
        }
    }

    public static List<List<String>> findAndRemoveDuplicates(List<List<String>> paths) {
        Map<String, List<String>> map = new HashMap<>();
        for (List<String> path : paths) {
            String key = String.join("/", path);
            map.put(key, path);
        }

        List<List<String>> result = new ArrayList<>();
        List<String> keys = new ArrayList<>(map.keySet());
        Collections.sort(keys);

        for (String key : keys) {
            if (!isMarked.containsKey(key)) {
                boolean isDuplicate = false;
                for (String otherKey : keys) {
                    if (!key.equals(otherKey) && isIdentical(map.get(key), map.get(otherKey))) {
                        isDuplicate = true;
                        break;
                    }
                }

                if (!isDuplicate) {
                    result.add(map.get(key));
                } else {
                    markIdentical(paths, key);
                }
            }
        }

        return result;
    }

    private static boolean isIdentical(List<String> path1, List<String> path2) {
        if (path1.size() != path2.size()) {
            return false;
        }

        for (int i = 0; i < path1.size(); i++) {
            if (!path1.get(i).equals(path2.get(i))) {
                return false;
            }
        }

        return true;
    }
}

