public class Solution {
    public long maxProduct(String s) {
        int n = s.length();
        long maxProd = 0;

        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                if ((j - i + 1) % 2 == 1 && isPalindrome(s.substring(i, j + 1))) {
                    for (int k = j + 1; k < n; k++) {
                        for (int l = k; l < n; l++) {
                            if ((l - k + 1) % 2 == 1 && isPalindrome(s.substring(k, l + 1))) {
                                maxProd = Math.max(maxProd, (long) (j - i + 1) * (l - k + 1));
                            }
                        }
                    }
                }
            }
        }

        return maxProd;
    }

    private boolean isPalindrome(String str) {
        int left = 0;
        int right = str.length() - 1;

        while (left < right) {
            if (str.charAt(left) != str.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }

        return true;
    }
}

