import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;

public class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int time = edge[2];
            graph.get(u).add(new int[]{v, time});
            graph.get(v).add(new int[]{u, time});
        }

        int[][] dp = new int[n][maxTime + 1];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }
        dp[0][0] = passingFees[0];

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);
        pq.offer(new int[]{0, 0, dp[0][0]});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int city = curr[0];
            int time = curr[1];
            int cost = curr[2];

            if (cost > dp[city][time]) continue;

            for (int[] neighbor : graph.get(city)) {
                int nextCity = neighbor[0];
                int nextTime = neighbor[1];
                int newTime = time + nextTime;

                if (newTime <= maxTime) {
                    int newCost = cost + passingFees[nextCity];
                    if (newCost < dp[nextCity][newTime]) {
                        dp[nextCity][newTime] = newCost;
                        pq.offer(new int[]{nextCity, newTime, newCost});
                    }
                }
            }
        }

        int minCost = Integer.MAX_VALUE;
        for (int i = 0; i <= maxTime; i++) {
            minCost = Math.min(minCost, dp[n - 1][i]);
        }

        return minCost == Integer.MAX_VALUE ? -1 : minCost;
    }
}

