import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[] maxGeneticDifference(int[] parents, int[][] queries) {
        int n = parents.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (parents[i] == -1) {
                root = i;
            } else {
                adj.get(parents[i]).add(i);
            }
        }

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int node = queries[i][0];
            int val = queries[i][1];

            List<Integer> path = new ArrayList<>();
            findPath(node, root, path);

            int maxDiff = 0;
            for (int p : path) {
                maxDiff = Math.max(maxDiff, val ^ p);
            }
            ans[i] = maxDiff;
        }
        return ans;
    }

    private boolean findPath(int node, int root, List<Integer> path) {
        if (node == root) {
            path.add(node);
            return true;
        }

        for (int parent : getParents(node)) {
            if (findPath(parent, root, path)) {
                path.add(node);
                return true;
            }
        }
        return false;
    }

    private List<Integer> getParents(int node) {
        List<Integer> parents = new ArrayList<>();
        for (int i = 0; i < parents.length; i++) {
            if (parents[i] == node) {
                parents.add(i);
            }
        }
        return parents;
    }
}

