public class Solution {
    public int minTimeToType(String word) {
        int currentTime = 0;
        int currentPosition = 0;
        int totalTime = 0;

        for (char c : word.toCharArray()) {
            int targetPosition = c - 'a';

            int clockwiseDistance = (targetPosition - currentPosition + 26) % 26;
            int counterClockwiseDistance = (currentPosition - targetPosition + 26) % 26;

            int distance = Math.min(clockwiseDistance, counterClockwiseDistance);
            totalTime += distance + 1;
            currentPosition = targetPosition;
        }

        return totalTime;
    }
}

