import java.util.HashSet;

public class Solution {
    public int longestCommonSubpath(int n, int[][] paths) {
        if (paths == null || paths.length == 0) {
            return 0;
        }

        int longestCommonLength = 0;
        for (int i = 0; i < paths[0].length; i++) {
            for (int j = i; j < paths[0].length; j++) {
                int[] subpath = new int[j - i + 1];
                for (int k = 0; k < subpath.length; k++) {
                    subpath[k] = paths[0][i + k];
                }

                boolean common = true;
                for (int k = 1; k < paths.length; k++) {
                    if (!isSubpath(paths[k], subpath)) {
                        common = false;
                        break;
                    }
                }

                if (common) {
                    longestCommonLength = Math.max(longestCommonLength, subpath.length);
                }
            }
        }

        return longestCommonLength;
    }

    private boolean isSubpath(int[] path, int[] subpath) {
        if (subpath.length == 0) {
            return true;
        }

        for (int i = 0; i <= path.length - subpath.length; i++) {
            boolean match = true;
            for (int j = 0; j < subpath.length; j++) {
                if (path[i + j] != subpath[j]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                return true;
            }
        }
        return false;
    }
}

