import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int nearestExit(char[][] maze, int[] entrance) {
        int m = maze.length;
        int n = maze[0].length;
        int row = entrance[0];
        int col = entrance[1];

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{row, col, 0});
        maze[row][col] = '+'; // Mark as visited

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            int steps = current[2];

            if (isExit(maze, r, c, row, col)) {
                return steps;
            }

            for (int[] dir : directions) {
                int newRow = r + dir[0];
                int newCol = c + dir[1];

                if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && maze[newRow][newCol] == '.') {
                    queue.offer(new int[]{newRow, newCol, steps + 1});
                    maze[newRow][newCol] = '+'; // Mark as visited
                }
            }
        }

        return -1;
    }

    private boolean isExit(char[][] maze, int row, int col, int entranceRow, int entranceCol) {
        int m = maze.length;
        int n = maze[0].length;

        if (row == 0 || row == m - 1 || col == 0 || col == n - 1) {
            return true;
        }
        return false;
    }
}

