public class Solution {
    public int removeBoxes(int[] boxes) {
        int n = boxes.length;
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            dp[i][i] = boxes[i];
        }

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                dp[i][j] = dp[i + 1][j];
                for (int k = i; k < j; k++) {
                    int score = 0;
                    int l = k;
                    while (l < j && boxes[l] == boxes[k]) {
                        l++;
                    }
                    score = (l - k) * (l - k) + dp[i][k] + dp[l][j];
                    dp[i][j] = Math.max(dp[i][j], score);
                }
            }
        }

        return dp[0][n - 1];
    }
}

