import java.util.ArrayList;
import java.util.List;

public class Solution {
    public String fractionAddition(String expression) {
        List<Fraction> fractions = parseExpression(expression);
        Fraction result = new Fraction(0, 1);

        for (Fraction fraction : fractions) {
            result = addFractions(result, fraction);
        }

        return simplifyFraction(result).toString();
    }

    private List<Fraction> parseExpression(String expression) {
        List<Fraction> fractions = new ArrayList<>();
        int sign = 1;
        int i = 0;
        while (i < expression.length()) {
            if (expression.charAt(i) == '-') {
                sign = -1;
                i++;
            } else if (expression.charAt(i) == '+') {
                sign = 1;
                i++;
            } else {
                int j = i;
                while (j < expression.length() && (Character.isDigit(expression.charAt(j)) || expression.charAt(j) == '.') ) {
                    j++;
                }
                String fractionStr = expression.substring(i, j);
                Fraction fraction = new Fraction(fractionStr);
                fraction.sign = sign;
                fractions.add(fraction);
                i = j;
            }
        }
        return fractions;
    }

    private Fraction addFractions(Fraction f1, Fraction f2) {
        int num = f1.num * f2.den + f2.num * f1.den;
        int den = f1.den * f2.den;
        return new Fraction(num, den);
    }

    private Fraction simplifyFraction(Fraction fraction) {
        int gcd = gcd(Math.abs(fraction.num), Math.abs(fraction.den));
        return new Fraction(fraction.num / gcd, fraction.den / gcd);
    }

    private int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }

    static class Fraction {
        int num;
        int den;
        int sign;

        public Fraction(int num, int den) {
            this.num = num;
            this.den = den;
            this.sign = 1;
        }

        public Fraction(String fractionStr) {
            int i = 0;
            int sign = 1;
            if (fractionStr.charAt(0) == '-') {
                sign = -1;
                i++;
            }
            int num = 0;
            while (i < fractionStr.length() && Character.isDigit(fractionStr.charAt(i))) {
                num = num * 10 + (fractionStr.charAt(i) - '0');
                i++;
            }
            this.num = num * sign;
            this.den = 1;
            this.sign = 1;
        }

        @Override
        public String toString() {
            int gcd = gcd(Math.abs(num), Math.abs(den));
            int simplifiedNum = num / gcd;
            int simplifiedDen = den / gcd;
            if (simplifiedDen == 1) {
                return String.valueOf(simplifiedNum);
            }
            return simplifiedNum + "/" + simplifiedDen;
        }
    }
}

