public class Solution {
    public char[][] updateBoard(char[][] board, int row, int col) {
        int m = board.length;
        int n = board[0].length;

        if (board[row][col] == 'M') {
            board[row][col] = 'X';
            return board;
        }

        if (board[row][col] != 'E') {
            return board;
        }

        int mineCount = 0;
        for (int i = row - 1; i <= row + 1; i++) {
            for (int j = col - 1; j <= col + 1; j++) {
                if (i >= 0 && i < m && j >= 0 && j < n && board[i][j] == 'M') {
                    mineCount++;
                }
            }
        }

        if (mineCount == 0) {
            board[row][col] = 'B';
            Queue<int[]> queue = new LinkedList<>();
            queue.offer(new int[]{row, col});

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];

                for (int i = r - 1; i <= r + 1; i++) {
                    for (int j = c - 1; j <= c + 1; j++) {
                        if (i >= 0 && i < m && j >= 0 && j < n && board[i][j] == 'E') {
                            board[i][j] = 'B';
                            queue.offer(new int[]{i, j});
                        }
                    }
                }
            }
        } else {
            board[row][col] = (char) ('0' + mineCount);
        }

        return board;
    }
}

