public class Solution {
    private int m;
    private int n;
    private Set<String> visited;
    private Random random;

    public Solution(int nRows, int nCols) {
        m = nRows;
        n = nCols;
        visited = new HashSet<>();
        random = new Random();
    }

    public int[] flip() {
        if (visited.size() == m * n) {
            reset();
        }

        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                String key = i + "," + j;
                if (!visited.contains(key)) {
                    count++;
                }
            }
        }

        int randomIndex = random.nextInt(count);
        int index = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                String key = i + "," + j;
                if (!visited.contains(key)) {
                    if (index == randomIndex) {
                        visited.add(key);
                        return new int[]{i, j};
                    }
                    index++;
                }
            }
        }

        return null;
    }

    public void reset() {
        visited.clear();
    }
}

