public class Solution {
    public Node intersect(Node n1, Node n2) {
        if (n1 == null && n2 == null) {
            return null;
        }
        if (n1 == null) {
            return n2;
        }
        if (n2 == null) {
            return n1;
        }

        if (n1.isLeaf && n2.isLeaf) {
            return new Node(n1.val || n2.val, true);
        }

        if (n1.isLeaf) {
            return new Node(n1.val || n2.val, false,
                    intersect(n2.topLeft, null),
                    intersect(n2.topRight, null),
                    intersect(n2.bottomLeft, null),
                    intersect(n2.bottomRight, null));
        }

        if (n2.isLeaf) {
            return new Node(n1.val || n2.val, false,
                    intersect(n1.topLeft, n2.topLeft),
                    intersect(n1.topRight, n2.topRight),
                    intersect(n1.bottomLeft, n2.bottomLeft),
                    intersect(n1.bottomRight, n2.bottomRight));
        }

        return new Node(false, false,
                intersect(n1.topLeft, n2.topLeft),
                intersect(n1.topRight, n2.topRight),
                intersect(n1.bottomLeft, n2.bottomLeft),
                intersect(n1.bottomRight, n2.bottomRight));
    }
}

