import java.math.BigInteger;

public class Solution {
    public String nearestPalindromic(String n) {
        BigInteger num = new BigInteger(n);
        int len = n.length();
        BigInteger[] candidates = new BigInteger[3];

        candidates[0] = new BigInteger(String.valueOf((long)Math.pow(10, len - 1) - 1));
        candidates[1] = new BigInteger("1".repeat(len + 1));
        BigInteger prefix = new BigInteger(n.substring(0, len - 1));
        BigInteger candidate = new BigInteger(String.valueOf(prefix).repeat(2) + (prefix.mod(new BigInteger("10"))));
        candidates[2] = candidate;

        BigInteger closest = null;
        long minDiff = Long.MAX_VALUE;

        for (BigInteger candidateNum : candidates) {
            if (candidateNum.equals(num)) continue;

            long diff = Math.abs(candidateNum.longValue() - num.longValue());

            if (diff < minDiff) {
                minDiff = diff;
                closest = candidateNum;
            } else if (diff == minDiff) {
                if (candidateNum.longValue() < closest.longValue()) {
                    closest = candidateNum;
                }
            }
        }

        return closest.toString();
    }
}

