public class Solution {
    public int findIntegers(int n) {
        int[] dp = new int[32];
        dp[0] = 1;
        dp[1] = 1;

        for (int i = 2; i < 32; i++) {
            dp[i] = dp[i - 1] + dp[i - 2];
        }

        int ans = 0;
        for (int i = 0; i < 32; i++) {
            if ((n & (1 << i)) != 0) {
                int prevBit = (n >> (i + 1)) & 1;
                if (prevBit == 1) {
                    ans += dp[i];
                } else {
                    ans += dp[i + 1];
                }
                if ((n >> i) == 0) {
                    break;
                }
            }
        }

        return ans + 1;
    }
}

