public class Solution {
    public int findUnsortedSubarray(int[] nums) {
        int n = nums.length;
        int start = -1, end = -1;

        // Find the start of the unsorted subarray
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] > nums[i + 1]) {
                start = i;
                break;
            }
        }

        if (start == -1) {
            return 0; // Already sorted
        }

        // Find the end of the unsorted subarray
        for (int i = n - 1; i > 0; i--) {
            if (nums[i] < nums[i - 1]) {
                end = i;
                break;
            }
        }

        // Find the minimum and maximum values within the unsorted subarray
        int subarrayMin = Integer.MAX_VALUE;
        int subarrayMax = Integer.MIN_VALUE;
        for (int i = start; i <= end; i++) {
            subarrayMin = Math.min(subarrayMin, nums[i]);
            subarrayMax = Math.max(subarrayMax, nums[i]);
        }

        // Extend the subarray to the left if necessary
        while (start > 0 && nums[start - 1] > subarrayMin) {
            start--;
        }

        // Extend the subarray to the right if necessary
        while (end < n - 1 && nums[end + 1] < subarrayMax) {
            end++;
        }

        return end - start + 1;
    }
}

