        calculateTilt(root, tiltSum);
        return tiltSum[0];
    }

    private int calculateTilt(TreeNode node, int[] tiltSum) {
        if (node == null) {
            return 0;
        }

        int leftTilt = calculateTilt(node.left, tiltSum);
        int rightTilt = calculateTilt(node.right, tiltSum);

