import java.util.Arrays;

public class Solution {
    public int findPaths(int m, int n, int maxMove, int startRow, int startColumn) {
        long MOD = 1000000007;
        int[][] dp = new int[maxMove + 1][];
        for (int i = 0; i <= maxMove; i++) {
            dp[i] = new int[m * n];
            Arrays.fill(dp[i], 0);
        }

        dp[0][startRow * n + startColumn] = 1;

        for (int moves = 1; moves <= maxMove; moves++) {
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    int index = i * n + j;

                    // Move up
                    if (i > 0) {
                        dp[moves][i * n + j] = (dp[moves][i * n + j] + dp[moves - 1][(i - 1) * n + j]) % MOD;
                    }
                    // Move down
                    if (i < m - 1) {
                        dp[moves][i * n + j] = (dp[moves][i * n + j] + dp[moves - 1][(i + 1) * n + j]) % MOD;
                    }
                    // Move left
                    if (j > 0) {
                        dp[moves][i * n + j] = (dp[moves][i * n + j] + dp[moves - 1][i * n + (j - 1)]) % MOD;
                    }
                    // Move right
                    if (j < n - 1) {
                        dp[moves][i * n + j] = (dp[moves][i * n + j] + dp[moves - 1][i * n + (j + 1)]) % MOD;
                    }
                }
            }
        }

        long result = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                result = (result + dp[maxMove][i * n + j]) % MOD;
            }
        }

        return (int) result;
    }
}

