import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public int[][] outerTrees(int[][] trees) {
        if (trees == null || trees.length == 0) {
            return new int[0][0];
        }

        int n = trees.length;
        if (n <= 3) {
            return trees;
        }

        Arrays.sort(trees, (a, b) -> {
            if (a[0] != b[0]) {
                return a[0] - b[0];
            }
            return a[1] - b[1];
        });

        List<int[]> hull = new ArrayList<>();

        // Build lower hull
        for (int[] tree : trees) {
            while (hull.size() >= 2 && crossProduct(hull.get(hull.size() - 2), hull.get(hull.size() - 1), tree) < 0) {
                hull.remove(hull.size() - 1);
            }
            hull.add(tree);
        }

        // Build upper hull
        int t = hull.size() + 1;
        for (int i = n - 2; i >= 0; i--) {
            int[] tree = trees[i];
            while (hull.size() >= t && crossProduct(hull.get(hull.size() - 2), hull.get(hull.size() - 1), tree) < 0) {
                hull.remove(hull.size() - 1);
            }
            hull.add(tree);
        }

        hull.remove(hull.size() - 1);

        Set<String> fencePoints = new HashSet<>();
        for (int[] point : hull) {
            fencePoints.add(point[0] + "," + point[1]);
        }

        int[][] result = new int[fencePoints.size()][2];
        int index = 0;
        for (int[] point : hull) {
            result[index++] = point;
        }

        return result;
    }

    private int crossProduct(int[] a, int[] b, int[] c) {
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
    }
}

