import java.util.Arrays;
public class Solution {
    public int checkRecord(int n) {
        long MOD = 1000000007;

        // dp[i][j][k] represents the number of valid attendance records of length i
        // where j is the number of 'A's and k is the length of the current streak of 'L's
        long[][][] dp = new long[n + 1][n + 1][3];

        // Base case: An empty record is always valid
        dp[0][0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                for (int k = 0; k < 3; k++) {
                    // Case 1: 'P'
                    dp[i][j][0] = (dp[i][j][0] + dp[i - 1][j][k]) % MOD;

                    // Case 1: 'L'
                    if (k < 2) {
                        dp[i][j][0] = (dp[i][j][0] + dp[i - 1][j][k + 1]) % MOD;
                    }

                    // Case 1: 'A'
                    if (j < n) {
                        dp[i][j + 1][0] = (dp[i][j + 1][0] + dp[i - 1][j][k]) % MOD;
                    }
                }
            }

            // Reset the dp array for the next iteration
            for (int j = 0; j <= n; j++) {
                Arrays.fill(dp[i][j], 0);
            }
        }

        long result = 0;
        for (int j = 0; j <= n; j++) {
            result = (result + dp[n][j][0]) % MOD;
        }

        return (int) result;
    }
}

