import java.util.Arrays;

public class Solution {
    private static final int MOD = 1000000007;

    public int numOfWays(int[] nums) {
        int n = nums.length;
        if (n <= 1) {
            return 1;
        }

        long[][] dp = new long[n + 1][n + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i - 1; j++) {
                dp[i][j] = dp[i - 1][j];
                if (j > 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD;
                }
            }
        }

        long result = 1;
        for (int i = 1; i <= n; i++) {
            result = (result * factorial(n - i + 1)) % MOD;
            result = (result * power(factorial(i), MOD - 2)) % MOD;
        }

        return (int) result;
    }

    private long factorial(int n) {
        long res = 1;
        for (int i = 1; i <= n; i++) {
            res = (res * i) % MOD;
        }
        return res;
    }

    private long power(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }
}

