public class Solution {
    public int unhappyFriends(int n, int[][] preferences, int[][] pairs) {
        int unhappyCount = 0;
        Map<Integer, Integer> pairing = new HashMap<>();
        for (int[] pair : pairs) {
            pairing.put(pair[0], pair[1]);
            pairing.put(pair[1], pair[0]);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j && pairing.get(i) != j) {
                    int partner = pairing.get(i);
                    for (int k = 0; k < n; k++) {
                        if (k != i && k != partner) {
                            int partnerOfK = pairing.get(k);
                            if (prefers(preferences[i], k, partner) && prefers(preferences[k], i, partnerOfK)) {
                                unhappyCount++;
                                break;
                            }
                        }
                    }
                }
            }
        return unhappyCount / 2;
    }

    private boolean prefers(int[] prefs, int a, int b) {
        for (int pref : prefs) {
            if (pref == a) {
                return true;
            }
            if (pref == b) {
                return false;
            }
        }
        return false;
    }
