public class Solution {
    public int minSubarray(int[] nums, int p) {
        int n = nums.length;
        long totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        if (totalSum % p == 0) {
            return 0;
        }

        int minLength = -1;

        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                long subarraySum = 0;
                for (int k = i; k <= j; k++) {
                    subarraySum += nums[k];
                }

                long remainingSum = totalSum - subarraySum;
                if (remainingSum % p == 0) {
                    int currentLength = j - i + 1;
                    if (minLength == -1 || currentLength < minLength) {
                        minLength = currentLength;
                    }
                }
            }
        }

        return minLength;
    }
}

