public class Solution {
    public int minOperationsMaxProfit(int[] customers, int boardingCost, int runningCost) {
        int rotations = 3;
        int maxProfit = -1;
        int currentCustomers = 0;
        int totalProfit = 0;
        int i = 0;

        while (i < customers.length || currentCustomers > 0) {
            if (i < customers.length) {
                currentCustomers += customers[i];
            }

            int boarding = Math.min(4, currentCustomers);
            currentCustomers -= boarding;

            totalProfit += boarding * boardingCost - runningCost;

