import java.util.Arrays;
import java.util.List;

public class Solution {
    public int connectTwoGroups(List<List<Integer>> cost) {
        int n = cost.size();
        int m = cost.get(0).size();

        int[][] dp = new int[1 << n][m];
        for (int i = 0; i < (1 << n); i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }
        dp[0][0] = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            for (int j = 0; j < m; j++) {
                if (dp[mask][j] == Integer.MAX_VALUE) continue;

                // Try connecting to the next point in the second group
                if (j + 1 < m) {
                    dp[mask][j + 1] = Math.min(dp[mask][j + 1], dp[mask][j]);
                }

                // Try connecting to the next point in the first group
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) == 0) {
                        int newMask = mask | (1 << i);
                        dp[newMask][j] = Math.min(dp[newMask][j], dp[mask][j] + cost.get(i).get(j));
                    }
                }
            }
        }

        int minCost = Integer.MAX_VALUE;
        for (int j = 0; j < m; j++) {
            minCost = Math.min(minCost, dp[(1 << n) - 1][j]);
        }

        return minCost;
    }
}

