public class Solution {
    public int minSwaps(int[][] grid) {
        int n = grid.length;
        int swaps = 0;
        int[] initialPositions = new int[n];
        for (int i = 0; i < n; i++) {
            initialPositions[i] = i;
        }

        for (int i = 0; i < n; i++) {
