import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int countPairs(TreeNode root, int distance) {
        List<TreeNode> leaves = new ArrayList<>();
        findLeaves(root, leaves);
        int count = 0;
        for (int i = 0; i < leaves.size(); i++) {
            for (int j = i + 1; j < leaves.size(); j++) {
                if (getDistance(root, leaves.get(i), leaves.get(j)) <= distance) {
                    count++;
                }
            }
        }
        return count;
    }

    private void findLeaves(TreeNode node, List<TreeNode> leaves) {
        if (node == null) {
            return;
        }
        if (node.left == null && node.right == null) {
            leaves.add(node);
            return;
        }
        findLeaves(node.left, leaves);
        findLeaves(node.right, leaves);
    }

    private int getDistance(TreeNode root, TreeNode node1, TreeNode node2) {
        List<TreeNode> path1 = new ArrayList<>();
        getPath(root, node1, path1);
        List<TreeNode> path2 = new ArrayList<>();
        getPath(root, node2, path2);

        int i = 0;
        while (i < path1.size() && i < path2.size() && path1.get(i) == path2.get(i)) {
            i++;
        }

        return path1.size() - i + path2.size() - i;
    }

    private boolean getPath(TreeNode root, TreeNode target, List<TreeNode> path) {
        if (root == null) {
            return false;
        }

        path.add(root);

        if (root == target) {
            return true;
        }

        if (getPath(root.left, target, path) || getPath(root.right, target, path)) {
            return true;
        }

        path.remove(path.size() - 1);
        return false;
    }
}

