import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int minDays(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;

        if (n == 0 || m == 0) {
            return 0;
        }

        int numIslands = countIslands(grid);

        if (numIslands <= 1) {
            return 0;
        }

        int minDays = numIslands - 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 1) {
                    int[][] tempGrid = new int[n][m];
                    for (int row = 0; row < n; row++) {
                        for (int col = 0; col < m; col++) {
                            tempGrid[row][col] = grid[row][col];
                        }
                    }
                    tempGrid[i][j] = 0;
                    int newIslands = countIslands(tempGrid);
                    minDays = Math.min(minDays, newIslands);
                }
            }
        }

        return minDays;
    }

    private int countIslands(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        boolean[][] visited = new boolean[n][m];
        int numIslands = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 1 && !visited[i][j]) {
                    dfs(grid, visited, i, j);
                    numIslands++;
                }
            }
        }

        return numIslands;
    }

    private void dfs(int[][] grid, boolean[][] visited, int row, int col) {
        int n = grid.length;
        int m = grid[0].length;

        if (row < 0 || row >= n || col < 0 || col >= m || grid[row][col] == 0 || visited[row][col]) {
            return;
        }

        visited[row][col] = true;

        dfs(grid, visited, row + 1, col);
        dfs(grid, visited, row - 1, col);
        dfs(grid, visited, row, col + 1);
        dfs(grid, visited, row, col - 1);
    }
}

