// #2022_04_09_Time_31_ms_(93.10%)_Space_51.7_MB_(98.80%)
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Queue;

public class Solution {
    public double maxProbability(int n, int[][] edges, double[] succProb, int start, int end) {
        List<List<Pair>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            adj.get(u).add(new Pair(v, succProb[i]));
            adj.get(v).add(new Pair(u, succProb[i]));
        }

        double[] prob = new double[n];
        prob[start] = 1.0;

        PriorityQueue<Pair> pq = new PriorityQueue<>((a, b) -> Double.compare(b.prob, a.prob));
        pq.offer(new Pair(start, 1.0));

        while (!pq.isEmpty()) {
            Pair curr = pq.poll();
            int u = curr.node;
            double p = curr.prob;

            if (p < prob[u]) continue;

            for (Pair neighbor : adj.get(u)) {
                int v = neighbor.node;
                double weight = neighbor.prob;
                double newProb = prob[u] * weight;

                if (newProb > prob[v]) {
                    prob[v] = newProb;
                    pq.offer(new Pair(v, prob[v]));
                }
            }
        }

        return prob[end];
    }

    static class Pair {
        int node;
        double prob;

        public Pair(int node, double prob) {
            this.node = node;
            this.prob = prob;
        }
    }
}

