// #Hard #Dynamic_Programming #Memoization #2022_04_11_Time_5_ms_(91.90%)_Space_43.5_MB_(31.90%)
import java.util.HashMap;
import java.util.Map;
public class Solution {
    public int minDays(int n) {
        if (n == 0) {
            return 0;
        }
        Map<Integer, Integer> memo = new HashMap<>();
        return solve(n, memo);
    }

    private int solve(int n, Map<Integer, Integer> memo) {
        if (n == 0) {
            return 0;
        }

        if (memo.containsKey(n)) {
            return memo.get(n);
        }

        int days = Integer.MAX_VALUE;

        days = Math.min(days, 1 + solve(n - 1, memo));

        if (n % 2 == 0) {
            days = Math.min(days, 1 + solve(n / 2, memo));
        }

        if (n % 3 == 0) {
            days = Math.min(days, 1 + solve(n - (2 * (n / 3)), memo));
        }

        memo.put(n, days);
        return days;
    }
}

