        if (n <= 1) {
            return 0;
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[2]));
        for (int i = 0; i < n; i++) {
            pq.offer(new int[]{0, i, 0});
        }

        int[] visited = new int[n];
        int cost = 0;
