                continue;
            }
            visited[u] |= 1;
            cost += curr[2];
            edges++;

            for (int v = 0; v < n; v++) {
                if ((visited[v] & 1) == 0) {
                    int dist = Math.abs(points[u][0] - points[v][0]) + Math.abs(points[u][1] - points[v][1]);
                    pq.offer(new int[]{u, v, dist});
                }
            }
        }

        return cost;
    }
