public class Solution {
    public int minNumberOperations(int[] target) {
        int n = target.length;
        Stack<Integer> stack = new Stack<>();
        int operations = 0;

        for (int i = 0; i < n; i++) {
            if (stack.isEmpty() || target[i] >= stack.peek()) {
                stack.push(target[i]);
            } else {
                while (target[i] < stack.peek()) {
                    stack.pop();
                    operations++;
                }
                stack.push(target[i]);
            }
        }

        return operations + 1;
    }
}

