public class Solution {
    public boolean isPrintable(int[][] targetGrid) {
        if (targetGrid == null || targetGrid.length == 0 || targetGrid[0].length == 0) {
            return true;
        }

        int rows = targetGrid.length;
        int cols = targetGrid[0].length;

        int[][] colorBound = new int[1001][4]; // Assuming colors are in the range [1, 1000]
        for (int i = 0; i < 1001; i++) {
            colorBound[i][0] = Integer.MAX_VALUE;
            colorBound[i][1] = Integer.MAX_VALUE;
            colorBound[i][2] = Integer.MIN_VALUE;
            colorBound[i][3] = Integer.MIN_VALUE;
        }

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int color = targetGrid[i][j];
                colorBound[color][0] = Math.min(colorBound[color][0], i);
                colorBound[color][1] = Math.min(colorBound[color][1], j);
                colorBound[color][2] = Math.max(colorBound[color][2], i);
                colorBound[color][3] = Math.max(colorBound[color][3], j);
            }
        }

        Set<Integer> printedColors = new HashSet<>();

        for (int color = 1; color <= 1000; color++) {
            if (colorBound[color][0] == Integer.MAX_VALUE) {
                continue; // Color not present in the grid
            }

            int row = colorBound[color][0];
            int col = colorBound[color][1];
            int maxRow = colorBound[color][2];
            int maxCol = colorBound[color][3];

            boolean canPrint = true;
            for (int i = row; i <= maxRow; i++) {
                for (int j = col; j <= maxCol; j++) {
                    if (targetGrid[i][j] != color) {
                        if (printedColors.contains(targetGrid[i][j])) {
                            canPrint = false;
                            break;
                        }
                    }
                }
                if (!canPrint) {
                    break;
                }
            }

            if (canPrint) {
                printedColors.add(color);
            } else {
                return false;
            }
        }

        return true;
    }
}

