    private int dfs(int node, List<List<Integer>> adj, String[] labels, boolean[] visited, int[] ans) {
        visited[node] = true;
        int count = 0;
        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor]) {
                count += dfs(neighbor, adj, labels, visited, ans);
            }
        }
        ans[node] = 0;
        if (labels[node].equals(labels[node])) {
            ans[node]++;
        }

        for (int neighbor : adj.get(node)) {
            if (labels[neighbor].equals(labels[node])) {
                ans[node]++;
            }
        }

        return ans[node];
    }
