public class Solution {
    public int maxUniqueSplit(String s) {
        return maxUniqueSplitHelper(s, 0, new HashSet<>());
    }

    private int maxUniqueSplitHelper(String s, int start, Set<String> used) {
        if (start == s.length()) {
            return 0;
        }

        int maxSplits = -1;
        for (int end = start + 1; end <= s.length(); end++) {
            String sub = s.substring(start, end);
            if (!used.contains(sub)) {
                used.add(sub);
                int splits = 1 + maxUniqueSplitHelper(s, end, used);
                maxSplits = Math.max(maxSplits, splits);
                used.remove(sub);
            }
        }
        return maxSplits;
    }
}

