public class Solution {
    public static class Tuple {
        long a;
        long b;

        public Tuple(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }

    public long maxNonNegativeProductPath(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        long MOD = 1000000007;

        Tuple[][] dpMax = new Tuple[m][n];
        Tuple[][] dpMin = new Tuple[m][n];

        dpMax[0][0] = new Tuple(grid[0][0], grid[0][0]);
        dpMin[0][0] = new Tuple(grid[0][0], grid[0][0]);

        for (int i = 1; i < m; i++) {
            dpMax[i][0] = new Tuple(dpMax[i - 1][0].a * grid[i][0], dpMax[i - 1][0].b * grid[i][0]);
            dpMin[i][0] = new Tuple(dpMin[i - 1][0].a * grid[i][0], dpMin[i - 1][0].b * grid[i][0]);
        }

        for (int j = 1; j < n; j++) {
            dpMax[0][j] = new Tuple(dpMax[0][j - 1].a * grid[0][j], dpMax[0][j - 1].b * grid[0][j]);
            dpMin[0][j] = new Tuple(dpMin[0][j - 1].a * grid[0][j], dpMin[0][j - 1].b * grid[0][j]);
        }

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                long upMaxA = dpMax[i - 1][j].a;
                long upMaxB = dpMax[i - 1][j].b;
                long upMinA = dpMin[i - 1][j].a;
                long upMinB = dpMin[i - 1][j].b;

                long leftMaxA = dpMax[i][j - 1].a;
                long leftMaxB = dpMax[i][j - 1].b;
                long leftMinA = dpMin[i][j - 1].a;
                long leftMinB = dpMin[i][j - 1].b;

                long maxA = Math.max(Math.max(upMaxA, leftMaxA), grid[i][j]);
                long maxB = Math.min(Math.min(upMaxA, leftMaxA), grid[i][j]);

                long minA = Math.min(Math.min(upMaxA, leftMaxA), grid[i][j]);
                long minB = Math.max(Math.max(upMaxA, leftMaxA), grid[i][j]);

                dpMax[i][j] = new Tuple(maxA, maxB);
                dpMin[i][j] = new Tuple(minA, minB);
            }
        }

        long result = dpMax[m - 1][n - 1].a;
        if (result < 0) {
            return -1;
        }
        return result % MOD;
    }
}

