public class Solution {
    public int numWays(String s) {
        int n = s.length();
        int ones = 0;
        for (char c : s.toCharArray()) {
            if (c == '1') {
                ones++;
            }
        }

        if (ones % 3 != 0) {
            return 0;
        }

        int onesPerPart = ones / 3;
        int MOD = 1000000007;

        int count = 0;
        int first = 0;
        int second = 0;
        int currentOnes = 0;

        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') {
                currentOnes++;
            }

            if (currentOnes == onesPerPart) {
                first++;
            } else if (currentOnes == 2 * onesPerPart) {
                second++;
            }
        }

        count = (int) (((long) first * second) % MOD);

        return count;
    }
}

