public class Solution {
    public int minLengthAfterCompression(String s, int k) {
        int n = s.length();
        int[][] dp = new int[n + 1][k + 1];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = Integer.MAX_VALUE;
            }
        }

        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                // Option 1: Delete the current character
                if (j > 0) {
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][j - 1]);
                }

                // Option 2: Keep the current character and compress it
                for (int l = 1; l <= i; l++) {
                    String sub = s.substring(i - l, i);
                    int count = 0;
                    boolean same = true;
                    for (int m = 1; m < sub.length(); m++) {
                        if (sub.charAt(m) != sub.charAt(0)) {
                            same = false;
                            break;
                        }
                    }
                    if (same) {
                        int len = String.valueOf(sub.length()).length();
                        int deleted = l - 1;
                        if (deleted <= j) {
                            dp[i][j] = Math.min(dp[i][j], dp[i - l][j - deleted] + len + 1);
                        }
                    }
                }
                if (dp[i][j] == Integer.MAX_VALUE) {
                    dp[i][j] = dp[i-1][j] + 1;
                }
            }
        }

        int minLen = Integer.MAX_VALUE;
        for (int j = 0; j <= k; j++) {
            minLen = Math.min(minLen, dp[n][j]);
        }

        return minLen;
    }
}

