public class Solution {
    public boolean containsCycle(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return false;
        }

        int m = grid.length;
        int n = grid[0].length;
        boolean[][] visited = new boolean[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i][j]) {
                    if (dfs(grid, i, j, -1, -1, visited)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private boolean dfs(char[][] grid, int row, int col, int parentRow, int parentCol, boolean[][] visited) {
        int m = grid.length;
        int n = grid[0].length;

        visited[row][col] = true;

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        for (int[] dir : directions) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];

            if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && grid[newRow][newCol] == grid[row][col]) {
                if (newRow == parentRow && newCol == parentCol) {
                    continue;
                }

                if (visited[newRow][newCol]) {
                    return true;
                }

                if (dfs(grid, newRow, newCol, row, col, visited)) {
                    return true;
                }
            }
        }

        return false;
    }
}

