        // Case 3: Change at most three elements
        if (n > 2) {
            minDiff = Math.min(minDiff, nums[n - 3] - nums[0]);
            minDiff = Math.min(minDiff, nums[n - 1] - nums[2]);
            minDiff = Math.min(minDiff, nums[n - 2] - nums[1]);
        }

        return minDiff;
    }
}

