public class Solution {
    public int countRoutes(int[] locations, int start, int finish, int fuel) {
        int n = locations.length;
        long[][] dp = new long[n][fuel + 1];
        dp[start][fuel] = 1;
        long MOD = 1000000007;

        for (int f = 0; f <= fuel; f++) {
            for (int i = 0; i < n; i++) {
                if (dp[i][f] > 0) {
                    for (int j = 0; j < n; j++) {
                        if (i != j) {
                            int cost = Math.abs(locations[i] - locations[j]);
                            if (f + cost <= fuel) {
