        long score2 = 0;
        long mod = 1000000007;
        int p1 = 0;
        int p2 = 0;
        boolean[] used1 = new boolean[nums1.length];
        boolean[] used2 = new boolean[nums2.length];

        while (p1 < nums1.length && p2 < nums2.length) {
            if (nums1[p1] == nums2[p2]) {
                score1 = (score1 + nums1[p1]) % mod;
                used1[p1] = true;
                used2[p2] = true;
                p1++;
                p2++;
            } else if (nums1[p1] < nums2[p2]) {
                if (!used1[p1]) {
                    score1 = (score1 + nums1[p1]) % mod;
                }
                p1++;
            } else {
                if (!used2[p2]) {
                    score2 = (score2 + nums2[p2]) % mod;
                }
                p2++;
            }
