        while (p1 < nums1.length) {
            if (!used1[p1]) {
                score1 = (score1 + nums1[p1]) % mod;
            }
            p1++;
        }

        while (p2 < nums2.length) {
            if (!used2[p2]) {
                score2 = (score2 + nums2[p2]) % mod;
            }
            p2++;
        }

        return (int) Math.max(score1, score2);
    }
