public class Solution {
    public int maxSumRangeQuery(int[] nums, int[][] requests) {
        int n = nums.length;
        long MOD = 1000000007;
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = (prefixSum[i] + nums[i]) % MOD;
        }

        long maxSum = 0;
        for (int[] request : requests) {
            int start = request[0];
            int end = request[1];
            long rangeSum = (prefixSum[end + 1] - prefixSum[start]) % MOD;
            if (rangeSum < 0) {
                rangeSum += MOD;
            }
            maxSum = (maxSum + rangeSum) % MOD;
        }

        return (int) maxSum;
    }
}

