public class Solution {
    public int stoneGameV(int[] stoneValue) {
        int n = stoneValue.length;
        int[][] dp = new int[n][n];

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                int sum = 0;
                for (int k = i; k <= j; k++) {
                    sum += stoneValue[k];
                }

                int maxScore = 0;
                for (int k = i; k < j; k++) {
                    int leftSum = 0;
                    for (int l = i; l <= k; l++) {
                        leftSum += stoneValue[l];
                    }
                    int rightSum = sum - leftSum;
                    int score = Math.min(leftSum, rightSum) + dp[i][k] + dp[k + 1][j];
                    maxScore = Math.max(maxScore, score);
                }
                dp[i][j] = maxScore;
            }
        }

        return dp[0][n - 1];
    }
}

