import java.util.Arrays;

public class Solution {
    public int maxNumEdgesToRemove(int n, int[][] edges) {
        int[] parentAlice = new int[n + 1];
        int[] parentBob = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            parentAlice[i] = i;
            parentBob[i] = i;
        }

        int count = 0;
        int removedEdges = 0;

        for (int i = edges.length - 1; i >= 0; i--) {
            int type = edges[i][0];
            int u = edges[i][1];
            int v = edges[i][2];

            if (type == 3) {
                if (find(parentAlice, u) != find(parentAlice, v)) {
                    union(parentAlice, u, v);
                    union(parentBob, u, v);
                    count++;
                } else {
                    removedEdges++;
                }
            } else if (type == 1) {
                if (find(parentAlice, u) != find(parentAlice, v)) {
                    union(parentAlice, u, v);
                    count++;
                } else {
                    removedEdges++;
                }
            } else {
                if (find(parentBob, u) != find(parentBob, v)) {
                    union(parentBob, u, v);
                    count++;
                } else {
                    removedEdges++;
                }
            }
        }

        if (count != n - 1) {
            return -1;
        }

        return removedEdges;
    }

    private int find(int[] parent, int i) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent, parent[i]);
    }

    private void union(int[] parent, int u, int v) {
        int rootU = find(parent, u);
        int rootV = find(parent, v);
        parent[rootU] = rootV;
    }
}

