public class Solution {
    /**
     * Given a 2D 0-indexed array of strings, accesstimes, with size n.
     * For each i where 0 <= i <= n - 1, accesstimes[i][0] represents the name of an employee,
     * and accesstimes[i][1] represents the access time of that employee.
     * All entries in accesstimes are within the same day.
     * The access time is represented as four digits using a 24-hour time format,
     * for example, "0800" or "2250".
     * An employee is said to be high-access if he has accessed the system three or more times
     * within a one-hour period. Times with exactly one hour of difference are not considered
     * part of the same one-hour period. For example, "0815" and "0915" are not part of the
     * same one-hour period. Access times at the start and end of the day are not counted
     * within the same one-hour period. For example, "0005" and "2350" are not part of the
     * same one-hour period.
     * Return a list that contains the names of high-access employees with any order you want.
     *
     * @param accesstimes The 2D array of access times.
     * @return A list of high-access employees.
     */
    public List<String> findHighAccessEmployees(String[][] accesstimes) {
        Map<String, List<Integer>> employeeAccessTimes = new HashMap<>();
        for (String[] accessTime : accesstimes) {
            String employeeName = accessTime[0];
            int accessTimeInt = Integer.parseInt(accessTime[1]);
            employeeAccessTimes.computeIfAbsent(employeeName, k -> new ArrayList<>()).add(accessTimeInt);
        }

        List<String> highAccessEmployees = new ArrayList<>();
        for (Map.Entry<String, List<Integer>> entry : employeeAccessTimes.entrySet()) {
            String employeeName = entry.getKey();
            List<Integer> accessTimes = entry.getValue();
            Collections.sort(accessTimes);

            for (int i = 0; i < accessTimes.size() - 1; i++) {
                int count = 1;
                int currentTime = accessTimes.get(i);
                for (int j = i + 1; j < accessTimes.size(); j++) {
                    if (accessTimes.get(j) >= currentTime + 60 && accessTimes.get(j) < currentTime + 60 + 60) {
                        count++;
                    }
                }
                if (count >= 3) {
                    highAccessEmployees.add(employeeName);
                    break;
                }
            }
        }

        return highAccessEmployees;
    }
}

