public class Solution {
    public boolean hasTrailingZeros(int[] nums) {
        if (nums == null || nums.length < 2) {
            return false;
        }

        for (int i = 0; i < (1 << nums.length); i++) {
            int orVal = 0;
            int count = 0;
            for (int j = 0; j < nums.length; j++) {
                if ((i >> j) % 2 == 1) {
                    orVal |= nums[j];
                    count++;
                }
            }

            if (count >= 2) {
                if (hasTrailingZero(orVal)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean hasTrailingZero(int n) {
        if (n == 0) {
            return true;
        }
        while (n % 2 == 0 && n > 0) {
            n /= 2;
        }
        return n > 0;
    }
}

