        int n = grid.length;
        Set<Integer> seen = new HashSet<>();
        int a = -1;
        int b = -1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (seen.contains(grid[i][j])) {
                    a = grid[i][j];
                } else {
                    seen.add(grid[i][j]);
                }
            }
        }

        long sum = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
