public class Solution {
    public long minCost(String source, String target, char[] original, char[] changed, int[] cost) {
        int n = source.length();
        long[][] dp = new long[n + 1][n + 1];

        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }

        dp[0][0] = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                if (dp[i][j] == Integer.MAX_VALUE) continue;

                if (source.charAt(i) == target.charAt(i)) {
                    dp[i + 1][j + 1] = Math.min(dp[i + 1][j + 1], dp[i][j]);
                } else {
                    for (int k = 0; k < cost.length; k++) {
                        if (original[k] == source.charAt(i) && changed[k] == target.charAt(i)) {
                            if (dp[i][j] != Integer.MAX_VALUE) {
                                dp[i + 1][j + 1] = Math.min(dp[i + 1][j + 1], dp[i][j] + cost[k]);
                            }
                        }
                    }
                }
            }
        }

        long minCost = Integer.MAX_VALUE;
        for (int i = 0; i <= n; i++) {
            minCost = Math.min(minCost, dp[n][i]);
        }

        if (minCost == Integer.MAX_VALUE) {
            return -1;
        }

        return minCost;
    }
}

