        List<Integer> subsequence = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (subsequence.isEmpty()) {
                subsequence.add(i);
            } else {
                int lastIndex = subsequence.get(subsequence.size() - 1);
                if (groups[i] != groups[lastIndex] && words[i].length() == words[lastIndex].length() && hammingDistance(words[i], words[lastIndex]) == 1) {
                    subsequence.add(i);
                }
            }
        }

        for (int index : subsequence) {
            result.add(words[index]);
        }

        return result;
    }

    private int hammingDistance(String s1, String s2) {
        int distance = 0;
        for (int i = 0; i < s1.length(); i++) {
            if (s1.charAt(i) != s2.charAt(i)) {
                distance++;
            }
        }
        return distance;
    }
}

