public class Solution {
    public int numberOfGoodPartitions(int[] nums) {
        int n = nums.length;
        int MOD = 1000000007;

        int[] lastOccurrence = new int[100001];
        for (int i = 0; i < 100001; i++) {
            lastOccurrence[i] = -1;
        }

        int[] dp = new int[n + 1];
        dp[0] = 1;

        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1];
            for (int j = 0; j < i; j++) {
