import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int numberOfSets(int n, int maxDistance, int[][] roads) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] road : roads) {
            int u = road[0];
            int v = road[1];
            int w = road[2];
            adj.get(u).add(new int[]{v, w});
            adj.get(v).add(new int[]{u, w});
        }

        int count = 0;
        for (int i = 0; i < (1 << n); i++) {
            List<Integer> remainingNodes = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if ((i >> j) % 2 == 0) {
                    remainingNodes.add(j);
                }
            }

            if (remainingNodes.isEmpty()) {
                continue;
            }

            boolean valid = true;
            for (int j = 0; j < remainingNodes.size(); j++) {
                for (int k = j + 1; k < remainingNodes.size(); k++) {
                    int startNode = remainingNodes.get(j);
                    int endNode = remainingNodes.get(k);

                    int distance = bfs(startNode, endNode, remainingNodes, adj);
                    if (distance > maxDistance) {
                        valid = false;
                        break;
                    }
                }
                if (!valid) {
                    break;
                }
            }

            if (valid) {
                count++;
            }
        }

        return count;
    }

    private int bfs(int startNode, int endNode, List<Integer> remainingNodes, List<List<int[]>> adj) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startNode, 0});
        boolean[] visited = new boolean[adj.size()];
        visited[startNode] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int node = current[0];
            int distance = current[1];

            if (node == endNode) {
                return distance;
            }

            for (int[] neighbor : adj.get(node)) {
                int nextNode = neighbor[0];
                int weight = neighbor[1];

                if (!visited[nextNode] && remainingNodes.contains(nextNode)) {
                    visited[nextNode] = true;
                    queue.offer(new int[]{nextNode, distance + weight});
                }
            }
        }

        return Integer.MAX_VALUE;
    }
}

