public class Solution {
    public long minIncrementOperations(int[] nums, int k) {
        int n = nums.length;
        long operations = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] < k) {
                operations += (long) (k - nums[i]);
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 2; j < n; j++) {
                int maxVal = nums[i];
                for (int l = i; l <= j; l++) {
                    maxVal = Math.max(maxVal, nums[l]);
                }
                if (maxVal < k) {
                    long diff = (long) (k - maxVal);
                    operations = Math.min(operations, diff);
                }
            }
        }

        if (n >= 3) {
            boolean beautiful = true;
            for (int i = 0; i <= n - 3; i++) {
                int maxVal = nums[i];
                for (int j = i + 1; j <= i + 2; j++) {
                    maxVal = Math.max(maxVal, nums[j]);
                }
                if (maxVal < k) {
                    beautiful = false;
                    break;
                }
            }
            if (!beautiful) {
                long ops = 0;
                for (int i = 0; i < n; i++) {
                    if (nums[i] < k) {
                        ops += (long) (k - nums[i]);
                    }
                }
                return ops;
            }
        }

        return operations;
    }
}

