public class Solution {
    public long maxSpending(int[][] values) {
        int m = values.length;
        int n = values[0].length;

        long totalSpending = 0;
        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> b.val - a.val);

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                pq.offer(new Node(values[i][j]));
            }
        }

        boolean[] bought = new boolean[m * n];
        int day = 1;

        while (!pq.isEmpty()) {
            Node node = pq.poll();
            int shop = -1;
            int item = -1;

            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    if (values[i][j] == node.val) {
                        shop = i;
                        item = j;
                        break;
                    }
                }
                if (shop != -1) break;
            }

            int index = shop * n + item;
            if (!bought[index]) {
                totalSpending += (long) node.val * day;
                bought[index] = true;
            }
            day++;
        }

        return totalSpending;
    }

    public static class Node {
        int val;

        public Node(int val) {
            this.val = val;
        }
    }
}

