public class Solution {
    public int[] lexicographicallySmallestArray(int[] nums, int limit) {
        int n = nums.length;
        int[] result = Arrays.copyOf(nums, n);
        List<Integer> connected = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            connected.add(i);
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (Math.abs(nums[i] - nums[j]) <= limit) {
                    int rootI = find(connected, i);
                    int rootJ = find(connected, j);
                    if (rootI != rootJ) {
                        if (nums[i] > nums[j]) {
                            int temp = nums[i];
                            nums[i] = nums[j];
                            nums[j] = temp;
                        }
                        connected.set(rootI, rootJ);
                    }
                }
            }
        }

        Arrays.sort(result);
        return result;
    }

    private int find(List<Integer> connected, int i) {
        if (connected.get(i) == i) {
            return i;
        }
        return find(connected, connected.get(i));
    }
}

