public class Solution {
    /**
     * You are given a binary string s and a positive integer k. A substring of s is beautiful if the number of 1's in it is exactly k.
     * Let len be the length of the shortest beautiful substring. Return the lexicographically smallest beautiful substring of string s with length equal to len.
     * If s doesn't contain a beautiful substring, return an empty string.
     * A string a is lexicographically larger than a string b (of the same length) if in the first position where a and b differ, a has a character strictly larger than the corresponding character in b.
     * For example, "abcd" is lexicographically larger than "abcc" because the first position they differ is at the fourth character, and d is greater than c.
     *
     * @param s the binary string
     * @param k the number of 1's in the beautiful substring
     * @return the lexicographically smallest beautiful substring of string s with length equal to len
     */
    public String findSmallestBeautifulSubstring(String s, int k) {
        int n = s.length();
        int minLen = Integer.MAX_VALUE;
        String smallestBeautifulSubstring = "";

        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                String sub = s.substring(i, j + 1);
                int count = 0;
                for (char c : sub.toCharArray()) {
                    if (c == '1') {
                        count++;
                    }
                }
                if (count == k) {
                    if (sub.length() < minLen) {
                        minLen = sub.length();
                        smallestBeautifulSubstring = sub;
                    } else if (sub.length() == minLen && sub.compareTo(smallestBeautifulSubstring) < 0) {
                        smallestBeautifulSubstring = sub;
                    }
                }
            }
        }

        return smallestBeautifulSubstring;
    }
}

