public class Solution {
    public int solve(int n) {
        long MOD = 1000000007;
        if (n < 4) {
            return 0;
        }

        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }

        long result = 0;
        for (int i = 0; i <= n - 4; i++) {
            long combinations = fact[n - 4 - i];
            combinations = (combinations * fact[i]) % MOD;
            result = (result + combinations) % MOD;
        }

        return (int) result;
    }
}

