public class Solution {
    public long distributeCandies(long n, long k) {
        if (n == 0) {
            return 1;
        }
        if (k == 0) {
            return 0;
        }

        long[][] dp = new long[n + 1][k + 1];
        dp[0][0] = 1;

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                if (i == 0 && j == 0) {
                    dp[i][j] = 1;
                    continue;
                }
                if (i == 0) {
                    dp[i][j] = 0;
                    continue;
                }
                if (j == 0) {
                    dp[i][j] = 0;
                    continue;
                }

                dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1] + dp[i - 1][j - 2];
                if (i < j) {
                    dp[i][j] = dp[i][j] - dp[i - 1][j];
                }
                if (i < 2 * j) {
                    dp[i][j] = dp[i][j] - dp[i - 1][j - 2];
                }
            }
        }

        return dp[n][k];
    }
}

