public class Solution {
    private int n;
    private List<List<Integer>> adj;
    private int[] values;
    private long maxScore;

    public long maximumScoreAfterOperations(int[][] edges, int[] values) {
        n = values.length;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        this.values = values;

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        maxScore = 0;
        dfs(0, -1);

        return maxScore;
    }

    private void dfs(int node, int parent) {
        long score = values[node];
        boolean isLeaf = true;
        for (int neighbor : adj.get(node)) {
            if (neighbor != parent) {
                isLeaf = false;
                dfs(neighbor, node);
            }
        }

        if (isLeaf) {
            maxScore = Math.max(maxScore, score);
        } else {
            long pathSum = 0;
            for (int neighbor : adj.get(node)) {
                if (neighbor != parent) {
                    pathSum += values[neighbor];
                }
            }
            if (pathSum != 0) {
                maxScore = Math.max(maxScore, score + pathSum);
            }
        }
    }
}

