                        if (len % d == 0) {
                            boolean isSemiPalindrome = true;
                            for (int m = 0; m < len / d; m++) {
                                for (int n1 = 0; n1 < d; n1++) {
                                    if (sub.charAt(m * d + n1) != sub.charAt((m + len / d) * d - 1 - n1)) {
                                        isSemiPalindrome = false;
                                        break;
                                    }
                                }
                                if (!isSemiPalindrome) break;
                            }
                            if (isSemiPalindrome) break;
                        }
                    }
                    if (dp[i][j] > dp[i - 1][j - 1]) {
                        dp[i][j] = dp[i - 1][j - 1];
