public class Solution {
    public boolean areSimilar(int[][] mat, int k) {
        int m = mat.length;
        int n = mat[0].length;

        int[][] original = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                original[i][j] = mat[i][j];
            }
        }

        for (int i = 0; i < m; i++) {
            if (i % 2 == 0) {
                // Even indexed rows: cyclically left shift k times
                int[] row = mat[i];
                int[] shiftedRow = new int[n];
                for (int j = 0; j < n; j++) {
                    shiftedRow[(j + k) % n] = row[j];
                }
                mat[i] = shiftedRow;
            } else {
                // Odd indexed rows: cyclically right shift k times
                int[] row = mat[i];
                int[] shiftedRow = new int[n];
                for (int j = 0; j < n; j++) {
                    shiftedRow[(j - k + n) % n] = row[j];
                }
                mat[i] = shiftedRow;
            }
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] != original[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }
}

