            if (i > 0 && Arrays.stream(sick).boxed().filter(s -> s == (i - 1)).findFirst().isPresent()) {
                dp[i] = dp[i-1];
            }
            if (i < n - 1 && Arrays.stream(sick).boxed().filter(s -> s == (i + 1)).findFirst().isPresent()) {
                dp[i] = (dp[i] + dp[i+1]) % MOD;
            }
            if (i > 0 && !Arrays.stream(sick).boxed().filter(s -> s == (i - 1)).findFirst().isPresent() && !Arrays.stream(sick).boxed().filter(s -> s == i).findFirst().isPresent()) {
                dp[i] = (dp[i] + dp[i-1]) % MOD;
            }
            if (i < n - 1 && !Arrays.stream(sick).boxed().filter(s -> s == (i + 1)).findFirst().isPresent() && !Arrays.stream(sick).boxed().filter(s -> s == i).findFirst().isPresent()) {
                dp[i] = (dp[i] + dp[i+1]) % MOD;
            }
        }

        long result = 1;
        for (int i = 0; i < n; i++) {
            result = (result * dp[i]) % MOD;
        }

