public class Solution {
    public int missingInteger(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }

        int maxLength = 0;
        int currentLength = 0;
        int sumOfLongestSequentialPrefix = 0;

        for (int i = 0; i < nums.length; i++) {
            if (i == 0) {
                currentLength = 1;
            } else {
                if (nums[i] == nums[i - 1] + 1) {
                    currentLength++;
                } else {
                    currentLength = 1;
                }
            }

            if (currentLength > maxLength) {
                maxLength = currentLength;
                sumOfLongestSequentialPrefix = nums[0];
                for (int j = 1; j < maxLength; j++) {
                    sumOfLongestSequentialPrefix += nums[j];
                }
            } else if (currentLength == maxLength) {
                int tempSum = nums[0];
                for (int j = 1; j < maxLength; j++) {
                    tempSum += nums[j];
                }
                sumOfLongestSequentialPrefix = Math.min(sumOfLongestSequentialPrefix, tempSum);
            }
        }

        int missing = sumOfLongestSequentialPrefix + 1;
        while (true) {
            boolean found = false;
            for (int num : nums) {
                if (num == missing) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                return missing;
            }
            missing++;
        }
    }
}

