public class Solution {
    public long[] placedCoins(int[][] edges, int[] cost) {
        int n = cost.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        long[] coins = new long[n];
        long[][] subtreeCosts = new long[n][];

        dfs(0, -1, adj, cost, subtreeCosts);

        for (int i = 0; i < n; i++) {
            if (subtreeCosts[i].length < 3) {
                coins[i] = 1;
            } else {
                long maxProduct = 0;
                for (int i = 0; i < subtreeCosts[i].length; i++) {
                    for (int j = i + 1; j < subtreeCosts[i].length; j++) {
                        for (int k = j + 1; k < subtreeCosts[i].length; k++) {
                            long product = subtreeCosts[i][i] * subtreeCosts[i][j] * subtreeCosts[i][k];
                            if (product > maxProduct) {
                                maxProduct = product;
                            }
                        }
                    }
                }
                if (maxProduct < 0) {
                    coins[i] = 0;
                } else {
                    coins[i] = maxProduct;
                }
            }
        }

        return coins;
    }

    private long[] dfs(int node, int parent, List<List<Integer>> adj, int[] cost, long[][] subtreeCosts) {
        List<Long> subtree = new ArrayList<>();
        subtree.add((long) cost[node]);

        for (int neighbor : adj.get(node)) {
            if (neighbor != parent) {
                long[] childSubtree = dfs(neighbor, node, adj, cost, subtreeCosts);
                for (long c : childSubtree) {
                    subtree.add(c);
                }
            }
        }

        subtreeCosts[node] = subtree.stream().mapToLong(Long::valueOf).toArray();
        return subtreeCosts[node];
    }
}

