public class Solution {
    public int countCompleteSubstrings(String word, int k) {
        int count = 0;
        for (int i = 0; i < word.length(); i++) {
            for (int j = i; j < word.length(); j++) {
                String sub = word.substring(i, j + 1);
                if (isComplete(sub, k)) {
