            }
        }

        for (int i = 0; i < sub.length() - 1; i++) {
            char c1 = sub.charAt(i);
            char c2 = sub.charAt(i + 1);
            if (Math.abs(c1 - c2) > 1) {
                return false;
            }
        }

        return true;
    }
}

