        boolean[] answer = new boolean[queries.length];

        for (int i = 0; i < queries.length; i++) {
            int a = queries[i][0];
            int b = queries[i][1];
            int c = queries[i][2];
            int d = queries[i][3];

            String s1 = s.substring(0, n / 2);
            String s2 = s.substring(n / 2);

            char[] arr1 = s1.toCharArray();
            char[] arr2 = s2.toCharArray();

            Arrays.sort(arr1);
            Arrays.sort(arr2);

            boolean possible = true;
            for (int j = 0; j < n / 2; j++) {
                if (arr1[j] != arr2[n / 2 - 1 - j]) {
                    possible = false;
                    break;
                }
            }

            if (possible) {
                answer[i] = true;
                continue;
            }

            String sub1 = s.substring(a, b + 1);
            String sub2 = s.substring(c, d + 1);

            char[] arrSub1 = sub1.toCharArray();
            char[] arrSub2 = sub2.toCharArray();

            Arrays.sort(arrSub1);
            Arrays.sort(arrSub2);

            boolean canMakePalindrome = false;

            if (n % 2 == 0) {
                if (a == 0 && b == n / 2 - 1 && c == n / 2 && d == n - 1) {
                    canMakePalindrome = true;
                } else {

                    if (a == 0 && b == n / 2 - 1) {

                        if (c == n / 2 && d == n - 1) {
                            canMakePalindrome = true;
                        }
                    } else if (c == n / 2 && d == n - 1) {
