                if (i != j) {
                    if (canReach(adj, j, i)) {
                        isChampion = false;
                        break;
                    }
                }
            }
            if (isChampion) {
                potentialChampions.add(i);
            }
        }

        if (potentialChampions.size() == 1) {
            return potentialChampions.get(0);
        } else {
            return -1;
        }
    }

    private boolean canReach(List<List<Integer>> adj, int start, int end) {
        boolean[] visited = new boolean[adj.size()];
        return dfs(adj, start, end, visited);
    }

    private boolean dfs(List<List<Integer>> adj, int current, int end, boolean[] visited) {
        if (current == end) {
            return true;
        }
        visited[current] = true;
        for (int neighbor : adj.get(current)) {
            if (!visited[neighbor]) {
                if (dfs(adj, neighbor, end, visited)) {
                    return true;
                }
            }
        }
        return false;
    }
}

