public class Solution {
    public int sumCounts(int[] nums) {
        int n = nums.length;
        long sum = 0;
        long mod = 1000000007;

        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                Set<Integer> distinct = new HashSet<>();
                for (int k = i; k <= j; k++) {
                    distinct.add(nums[k]);
                }
