import java.util.Queue;

public class Solution {
    public int minimumOperationsToMakeEqual(int x, int y) {
        if (x == y) {
            return 0;
        }

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{x, 0});
        boolean[][] visited = new boolean[x + 1][y + 1];
        visited[x][y] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int currentX = current[0];
            int operations = current[1];

            if (currentX == y) {
                return operations;
            }

            // Operation 1: Divide by 11
            if (currentX % 11 == 0) {
                int nextX = currentX / 11;
                if (nextX <= x && nextX <= y && !visited[nextX][y]) {
                    queue.offer(new int[]{nextX, operations + 1});
                    visited[nextX][y] = true;
                }
            }

            // Operation 2: Divide by 5
            if (currentX % 5 == 0) {
                int nextX = currentX / 5;
                if (nextX <= x && nextX <= y && !visited[nextX][y]) {
                    queue.offer(new int[]{nextX, operations + 1});
                    visited[nextX][y] = true;
                }
            }

            // Operation 3: Decrement
            int nextXDecrement = currentX - 1;
            if (nextXDecrement >= 0 && nextXDecrement <= x && nextXDecrement <= y && !visited[nextXDecrement][y]) {
                queue.offer(new int[]{nextXDecrement, operations + 1});
                visited[nextXDecrement][y] = true;
            }

            // Operation 4: Increment
            int nextXIncrement = currentX + 1;
            if (nextXIncrement >= 0 && nextXIncrement <= x && nextXIncrement <= y && !visited[nextXIncrement][y]) {
                queue.offer(new int[]{nextXIncrement, operations + 1});
                visited[nextXIncrement][y] = true;
            }
        }

        return -1; // Should not happen if x and y are positive
    }
}

