public class Solution {
    public int minOperations(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) {
            return 0;
        }

        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int num : nums) {
            pq.offer(num);
        }

        int operations = 0;
        while (pq.size() >= 2 && pq.peek() < k) {
            int x = pq.poll();
            int y = pq.poll();
            pq.offer(x + 2 + y);
            operations++;
        }

        if (pq.size() == 1 && pq.peek() < k) {
            return -1;
        }

        return operations;
    }
}

