public class Solution {
    public int minOrAfterOperations(int[] nums, int k) {
        int n = nums.length;
        if (n == 1) {
            return nums[0];
        }

        if (k >= n - 1) {
            return 0;
        }

        int minOr = Integer.MAX_VALUE;

        for (int i = 0; i < (1 << (n - 1)); i++) {
            if (Integer.bitCount(i) > k) {
                continue;
            }

            int[] tempNums = Arrays.copyOf(nums, nums.length);
            int ops = 0;

            for (int j = 0; j < n - 1; j++) {
                if ((i & (1 << j)) != 0) {
                    tempNums[j] = tempNums[j] & tempNums[j + 1];
                    tempNums[j + 1] = -1;
                    ops++;
                }
            }

            int orVal = 0;
            for (int num : tempNums) {
                if (num != -1) {
                    orVal |= num;
                }
            }
            minOr = Math.min(minOr, orVal);
        }

        return minOr;
    }
}

