import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int minimumBoxes(int[] apple, int[] capacity) {
        Arrays.sort(apple);
        Arrays.sort(capacity);

        PriorityQueue<Integer> boxCapacity = new PriorityQueue<>();
        for (int cap : capacity) {
            boxCapacity.offer(cap);
        }

        int boxesUsed = 0;
        for (int apples : apple) {
            if (boxCapacity.isEmpty()) {
                return -1;
            }

            int boxCapacityVal = boxCapacity.poll();
            boxCapacityVal -= apples;

            if (boxCapacityVal > 0) {
                boxCapacity.offer(boxCapacityVal);
            }
            boxesUsed++;
        }

        return boxesUsed;
    }
}

