public class Solution {
    public int minimumSubarrayLength(int[] nums, int k) {
        int minLength = Integer.MAX_VALUE;
        int currentOr = 0;
        int left = 0;

        for (int right = 0; right < nums.length; right++) {
            currentOr |= nums[right];

