public class Solution {
    public int earliestSecondToMarkIndices(int[] nums, int[] changeIndices) {
        int n = nums.length;
        int m = changeIndices.length;

        Set<Integer> marked = new HashSet<>();
        for (int i = 0; i < n; i++) {
            if (nums[i] == 0) {
                marked.add(i + 1);
            }
        }

        if (marked.size() == n) {
            return 1;
        }

        for (int s = 1; s <= m; s++) {
            int changeIndex = changeIndices[s - 1];
            nums[changeIndex - 1] = Math.max(0, nums[changeIndex - 1] - 1);

            Set<Integer> newlyMarked = new HashSet<>();
            for (int i = 0; i < n; i++) {
                if (nums[i] == 0 && !marked.contains(i + 1)) {
                    newlyMarked.add(i + 1);
                }
            }

            marked.addAll(newlyMarked);

            if (marked.size() == n) {
                return s;
            }
        }

        return -1;
    }
}

