public class Solution {
    public int[] distributeElements(int[] nums) {
        List<Integer> arr1 = new ArrayList<>();
        List<Integer> arr2 = new ArrayList<>();

        if (nums.length == 0) {
            return new int[0];
        }

        if (nums.length == 1) {
            return new int[]{nums[0]};
        }

        arr1.add(nums[1]);
        arr2.add(nums[2]);

        for (int i = 3; i < nums.length; i++) {
            int count1 = greaterCount(arr1, nums[i]);
            int count2 = greaterCount(arr2, nums[i]);

            if (count1 > count2) {
                arr1.add(nums[i]);
            } else if (count1 < count2) {
                arr2.add(nums[i]);
            } else {
                if (arr1.size() <= arr2.size()) {
                    arr1.add(nums[i]);
                } else {
                    arr2.add(nums[i]);
                }
            }
        }

        int[] result = new int[arr1.size() + arr2.size()];
        System.arraycopy(arr1.stream().mapToInt(Integer::intValue).toArray(), 0, result, 0, arr1.size());
        System.arraycopy(arr2.stream().mapToInt(Integer::intValue).toArray(), 0, result, arr1.size(), arr2.size());

        return result;
    }

    private int greaterCount(List<Integer> arr, int val) {
        int count = 0;
        for (int num : arr) {
            if (num > val) {
                count++;
            }
        }
        return count;
    }
}

