import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[][] resultGrid(int[][] image, int threshold) {
        int m = image.length;
        int n = image[0].length;
        int[][] result = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                List<Region> regions = new ArrayList<>();

                // Check adjacent regions
                if (i > 0) {
                    regions.add(new Region(image, i - 1, j, threshold));
                }
                if (i < m - 1) {
                    regions.add(new Region(image, i + 1, j, threshold));
                }
                if (j > 0) {
                    regions.add(new Region(image, i, j - 1, threshold));
                }
                if (j < n - 1) {
                    regions.add(new Region(image, i, j + 1, threshold));
                }

                if (regions.isEmpty()) {
                    result[i][j] = image[i][j];
                } else {
                    long sum = 0;
                    for (Region region : regions) {
                        sum += region.averageIntensity();
                    }
                    result[i][j] = (int) (sum / regions.size());
                }
            }
        }

        return result;
    }

    private class Region {
        private int row;
        private int col;
        private int[][] image;
        private int threshold;

        public Region(int[][] image, int row, int col, int threshold) {
            this.image = image;
            this.row = row;
            this.col = col;
            this.threshold = threshold;
        }

        public long averageIntensity() {
            int sum = 0;
            int count = 0;
            for (int i = row - 1; i <= row + 1; i++) {
                for (int j = col - 1; j <= col + 1; j++) {
                    if (i >= 0 && i < image.length && j >= 0 && j < image[0].length) {
                        boolean valid = true;
                        for (int x = Math.max(0, row - 1); x <= Math.min(image.length - 1, row + 1); x++) {
                            for (int y = Math.max(0, col - 1); y <= Math.min(image[0].length - 1, col + 1); y++) {
                                if (x != row || y != col) {
                                    if (Math.abs(image[row][col] - image[x][y]) > threshold) {
                                        valid = false;
                                        break;
                                    }
                                }
                            }
                            if (!valid) break;
                        }
                        if (valid) {
                            sum += image[i][j];
                            count++;
                        }
                    }
                }
            return (long) sum;
        }
    }
}

