import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[] countPairsOfConnectableServers(int[][] edges, int signalSpeed) {
        int n = edges.length + 1;
        List<List<Pair>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int weight = edge[2];
            adj.get(u).add(new Pair(v, weight));
            adj.get(v).add(new Pair(u, weight));
        }

        int[] count = new int[n];
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (isConnectable(i, j, adj, signalSpeed, n)) {
                    count[i]++;
                    count[j]++;
                }
            }
        }

        return count;
    }

    private boolean isConnectable(int a, int b, List<List<Pair>> adj, int signalSpeed, int n) {
        for (int c = 0; c < n; c++) {
            if (a < b && a != c && b != c) {
                if (isReachable(a, c, adj, new boolean[n], signalSpeed) &&
                        isReachable(b, c, adj, new boolean[n], signalSpeed) &&
                        !sharePath(a, b, c, adj)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isReachable(int start, int end, List<List<Pair>> adj, boolean[] visited, int signalSpeed) {
        visited[start] = true;
        if (start == end) {
            return true;
        }

        for (Pair neighbor : adj.get(start)) {
            if (!visited[neighbor.node] && neighbor.weight % signalSpeed == 1) {
                if (isReachable(neighbor.node, end, adj, visited, signalSpeed)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean sharePath(int a, int b, int c, List<List<Pair>> adj) {
        List<Integer> pathA = getPath(a, c, adj, new boolean[adj.size()], new ArrayList<>());
        List<Integer> pathB = getPath(b, c, adj, new boolean[adj.size()], new ArrayList<>());

        if (pathA == null || pathB == null) {
            return false;
        }

        for (int node : pathA) {
            if (pathB.contains(node)) {
                return true;
            }
        }
        return false;
    }

    private List<Integer> getPath(int start, int end, List<List<Pair>> adj, boolean[] visited, List<Integer> path) {
        visited[start] = true;
        path.add(start);

        if (start == end) {
            return path;
        }

        for (Pair neighbor : adj.get(start)) {
            if (!visited[neighbor.node]) {
                List<Integer> newPath = getPath(neighbor.node, end, adj, visited, new ArrayList<>(path));
                if (newPath != null) {
                    return newPath;
                }
            }
        }

        return null;
    }

    private static class Pair {
        int node;
        int weight;

        public Pair(int node, int weight) {
            this.node = node;
            this.weight = weight;
        }
    }
}

