public class Solution {
    public int findGreatestInteger(int k, int x) {
        int low = 1;
        int high = 100000;
        int ans = 0;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            long priceSum = 0;
            for (int i = 1; i <= mid; i++) {
                priceSum += calculatePrice(i, x);
            }

            if (priceSum <= k) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return ans;
    }

    private int calculatePrice(int num, int x) {
        int price = 0;
        String binary = Integer.toBinaryString(num);
        for (int i = 0; i < binary.length(); i++) {
            if (binary.charAt(binary.length() - 1 - i) == '1' && (i + 1) % x == 0) {
                price++;
            }
        }
        return price;
    }
}

