public class Solution {
    public int maxPartitionsAfterOperations(String s, int k) {
        int n = s.length();
        int maxPartitions = 0;

        for (int i = 0; i < n; i++) {
            char originalChar = s.charAt(i);
            for (char c = 'a'; c <= 'z'; c++) {
                if (c != originalChar) {
                    StringBuilder sb = new StringBuilder(s);
                    sb.setCharAt(i, c);
                    String modifiedS = sb.toString();
                    maxPartitions = Math.max(maxPartitions, partitions(modifiedS, k));
                }
            }
            maxPartitions = Math.max(maxPartitions, partitions(s, k));
        }

        return maxPartitions;
    }

    private int partitions(String s, int k) {
        int n = s.length();
        int partitions = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            Set<Character> distinctChars = new HashSet<>();
            while (j < n && distinctChars.size() <= k) {
                distinctChars.add(s.charAt(j));
                j++;
            }
            partitions++;
            i = j;
        }
        return partitions;
    }
}

