public class Solution {
    public long[] countOfPairs(int n, int x, int y) {
        long[] result = new long[n + 1];
        for (int k = 1; k <= n; k++) {
            for (int start = 1; start <= n; start++) {
                for (int end = 1; end <= n; end++) {
                    if (start == end) continue;
                    int dist = bfs(n, start, end, x, y);
                    if (dist == k) {
                        result[k]++;
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            result[i] = result[i] / 2;
        }

        return result;
    }

    private int bfs(int n, int start, int end, int x, int y) {
        int[] dist = new int[n + 1];
        Arrays.fill(dist, -1);
        dist[start] = 0;
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(start);

        while (!queue.isEmpty()) {
            int u = queue.poll();

            if (u == end) {
                return dist[end];
            }

            int v1 = u + 1;
            if (v1 <= n && dist[v1] == -1) {
                dist[v1] = dist[u] + 1;
                queue.offer(v1);
            }

            int v2 = u - 1;
            if (v2 >= 1 && dist[v2] == -1) {
                dist[v2] = dist[u] + 1;
                queue.offer(v2);
            }
        }

        if (x == y) {
            return 0;
        }

        if (start == x && end == y) {
            return 1;
        }
        if (start == y && end == x) {
            return 1;
        }

        if (x == start && y == end) {
            return 1;
        }
        if (x == end && y == start) {
            return 1;
        }

        if (dist[end] == -1) {
            return Integer.MAX_VALUE;
        }

        return dist[end];
    }
}

