        while (!queue.isEmpty()) {
            int u = queue.poll();

            int[] neighbors = getNeighbors(u, n, x, y);
            for (int v : neighbors) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    queue.offer(v);
                }
            }
        }

        return dist[end];
