public class Solution {
    public long maximumStrength(int[] n, int k) {
        int n_len = n.length;
        long[] prefixSum = new long[n_len + 1];
        for (int i = 0; i < n_len; i++) {
            prefixSum[i + 1] = prefixSum[i] + n[i];
        }

        long maxStrength = Long.MIN_VALUE;
        for (int i = 0; i < (1 << n_len); i++) {
            if (Integer.bitCount(i) != k) {
                continue;
            }

            long currentStrength = 0;
            int subarraysCount = 0;
            int lastIndex = -1;

            for (int j = 0; j < n_len; j++) {
                if ((i >> j) & 1) {
                    if (lastIndex == -1) {
                        lastIndex = j;
                    }
                } else {
                    if (lastIndex != -1) {
                        int subarrayLength = j - lastIndex;
                        long subarraySum = prefixSum[j] - prefixSum[lastIndex];
                        currentStrength += (-1) * (long)subarraySum * (long)(subarrayLength);
                        lastIndex = -1;
                        subarraysCount++;
                    }
                }
            }

            if (lastIndex != -1) {
                int subarrayLength = n_len - lastIndex;
                long subarraySum = prefixSum[n_len] - prefixSum[lastIndex];
                currentStrength += (-1) * (long)subarraySum * (long)(subarrayLength);
                subarraysCount++;
            }

            maxStrength = Math.max(maxStrength, currentStrength);
        }

        return maxStrength;
    }
}

