public class Solution {
    public int sumOfPowerSubsequences(int[] nums, int k) {
        int n = nums.length;
        long sum = 0;
        long mod = 1000000007;

        if (k > n) {
            return 0;
        }

        for (int i = 0; i < (1 << n); i++) {
            if (Integer.bitCount(i) == k) {
                int[] subsequence = new int[k];
                int index = 0;
                for (int j = 0; j < n; j++) {
                    if ((i >> j) % 2 == 1) {
                        subsequence[index++] = nums[j];
                    }
                }

                Arrays.sort(subsequence);

                int minAbsDiff = Integer.MAX_VALUE;
                for (int j = 0; j < k - 1; j++) {
                    minAbsDiff = Math.min(minAbsDiff, Math.abs(subsequence[j] - subsequence[j + 1]));
                }

                sum = (sum + minAbsDiff) % mod;
            }
        }

        return (int) sum;
    }
}

