import java.util.ArrayList;
import java.util.List;

public class Solution {

    public int[] findNodesWithHighestScore(int[] parents, int[] scores) {
        int n = parents.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int i = 1; i < n; i++) {
            adj.get(parents[i]).add(i);
        }

        long[] subtreeSizes = new long[n];
        long[] subtreeScores = new long[n];

        dfs(0, -1, adj, scores, subtreeSizes, subtreeScores);

        long maxScore = 0;
        for (int i = 0; i < n; i++) {
            maxScore = Math.max(maxScore, subtreeScores[i]);
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (subtreeScores[i] == maxScore) {
                result.add(i);
            }
        }

        int[] resultArray = new int[result.size()];
        for (int i = 0; i < result.size(); i++) {
            resultArray[i] = result.get(i);
        }

        return resultArray;
    }

    private long dfs(int node, int parent, List<List<Integer>> adj, int[] scores, long[] subtreeSizes, long[] subtreeScores) {
        subtreeSizes[node] = 1;
        subtreeScores[node] = 1;

        for (int child : adj.get(node)) {
            if (child != parent) {
                subtreeSizes[node] += dfs(child, node, adj, scores, subtreeSizes, subtreeScores);
                subtreeScores[node] *= subtreeScores[child];
            }
        }

        return subtreeSizes[node];
    }
}

