public class Solution {
    public int minCost(int[] startPos, int[] homePos, int[] rowCosts, int[] colCosts) {
        int startRow = startPos[0];
        int startCol = startPos[1];
        int homeRow = homePos[0];
        int homeCol = homePos[1];
        int m = rowCosts.length;
        int n = colCosts.length;

        int[][] dist = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                dist[i][j] = Integer.MAX_VALUE;
            }
        }
        dist[startRow][startCol] = 0;

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startRow, startCol});

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int row = curr[0];
            int col = curr[1];

            for (int i = 0; i < 4; i++) {
                int newRow = row + dr[i];
                int newCol = col + dc[i];

                if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n) {
                    int cost = 0;
                    if (dr[i] == -1 || dr[i] == 1) {
                        cost = rowCosts[newRow];
                    } else {
                        cost = colCosts[newCol];
                    }

                    if (dist[row][col] + cost < dist[newRow][newCol]) {
                        dist[newRow][newCol] = dist[row][col] + cost;
                        queue.offer(new int[]{newRow, newCol});
                    }
                }
            }
        }

        return dist[homeRow][homeCol];
    }
}

