    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        boolean[] result = new boolean[requests.length];
        for (int i = 0; i < requests.length; i++) {
            int u = requests[i][0];
            int v = requests[i][1];

            if (canBecomeFriends(u, v, restrictions)) {
                union(u, v);
                result[i] = true;
            } else {
                result[i] = false;
            }
        }

        return result;
    }

    private int find(int i) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent[i]);
    }

    private void union(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);
        if (rootU != rootV) {
            parent[rootU] = rootV;
        }
    }

    private boolean canBecomeFriends(int u, int v, int[][] restrictions) {
        int rootU = find(u);
        int rootV = find(v);

        if (rootU == rootV) {
            return true;
        }

        for (int[] restriction : restrictions) {
            int x = restriction[0];
            int y = restriction[1];
            if ((find(x) == find(u) && find(y) == find(v)) || (find(x) == find(v) && find(y) == find(u))) {
                return false;
            }
        }

        return true;
    }
}

