public class Solution {
    public boolean placeWordInCrossword(char[][] board, String word) {
        int m = board.length;
        int n = board[0].length;

        // Check horizontal placement
        for (int i = 0; i < m; i++) {
            for (int j = 0; j <= n - word.length(); j++) {
                if (canPlaceHorizontal(board, word, i, j)) {
                    return true;
                }
            }
        }

        // Check vertical placement
        for (int j = 0; j < n; j++) {
            for (int i = 0; i <= m - word.length(); i++) {
                if (canPlaceVertical(board, word, i, j)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean canPlaceHorizontal(char[][] board, String word, int row, int col) {
        if (col + word.length() > board[0].length) {
            return false;
        }

        for (int i = 0; i < word.length(); i++) {
            if (board[row][col + i] != ' ' && board[row][col + i] != word.charAt(i)) {
                return false;
            }
        }

        // Check for empty cells to the left
        if (col > 0) {
            for (int k = 0; k < col; k++) {
                if (board[row][k] != '#') {
                    return false;
                }
            }
        }

        // Check for empty cells to the right
        if (col + word.length() < board[0].length) {
            for (int k = col + word.length(); k < board[0].length; k++) {
                if (board[row][k] != '#') {
                    return false;
                }
            }
        }

        return true;
    }

    private boolean canPlaceVertical(char[][] board, String word, int row, int col) {
        if (row + word.length() > board.length) {
            return false;
        }

        for (int i = 0; i < word.length(); i++) {
            if (board[row + i][col] != ' ' && board[row + i][col] != word.charAt(i)) {
                return false;
            }
        }

        // Check for empty cells above
        if (row > 0) {
            for (int k = 0; k < row; k++) {
                if (board[k][col] != '#') {
                    return false;
                }
            }
        }

        // Check for empty cells below
        if (row + word.length() < board.length) {
            for (int k = row + word.length(); k < board.length; k++) {
                if (board[k][col] != '#') {
                    return false;
                }
            }
        }

        return true;
    }
}

