public class Solution {
    public int minimizedMaximum(int n, int[] q) {
        int left = 1;
        int right = 0;
        for (int quantity : q) {
            right = Math.max(right, quantity);
        }

        int ans = right;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            int storesNeeded = 0;
            for (int quantity : q) {
                storesNeeded += (quantity + mid - 1) / mid;
            }

            if (storesNeeded <= n) {
                ans = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return ans;
    }
}

