                    int num = 100 * digits[i] + 10 * digits[j] + digits[k];
                    if (num % 2 == 0 && digits[i] != 0) {
                        uniqueEvenNumbers.add(num);
                    }
                }
            }
        }
        int[] result = new int[uniqueEvenNumbers.size()];
        int index = 0;
        for (int num : uniqueEvenNumbers) {
            result[index++] = num;
        }
        Arrays.sort(result);
        return result;
    }
}

