import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public static class Node {
        int val;
        int time;

        public Node(int val, int time) {
            this.val = val;
            this.time = time;
        }
    }

    public int maxQuality(int n, int[][] edges, int maxTime, int[] values) {
        List<List<Node>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int time = edge[2];
            adj.get(u).add(new Node(v, time));
            adj.get(v).add(new Node(u, time));
        }

        int maxQuality = 0;
        boolean[] visited = new boolean[n];

        maxQuality = dfs(0, 0, maxTime, values, adj, visited, new HashSet<>());

        return maxQuality;
    }

    private int dfs(int node, int currentTime, int maxTime, int[] values, List<List<Node>> adj, boolean[] visited, Set<Integer> uniqueNodes) {
        if (node == 0 && currentTime <= maxTime) {
            int quality = 0;
            for (int uniqueNode : uniqueNodes) {
                quality += values[uniqueNode];
            }
            return quality;
        }

        int maxQuality = 0;
        visited[node] = true;
        uniqueNodes.add(node);

        for (Node neighbor : adj.get(node)) {
            int nextTime = currentTime + neighbor.time;
            if (nextTime <= maxTime) {
                int quality = dfs(neighbor.val, nextTime, maxTime, values, adj, visited, new HashSet<>(uniqueNodes));
                maxQuality = Math.max(maxQuality, quality);
            }
        }

        visited[node] = false;
        uniqueNodes.remove(node);

        return maxQuality;
    }
}

