import java.util.List;
import java.util.Map;

public class Solution {
    public int waysToPartition(int[] nums, int k) {
        int n = nums.length;
        int maxWays = 0;

        // Calculate ways without changing any element
        int ways = 0;
        long totalSum = 0;
        for (int i = 0; i < n; i++) {
            totalSum += nums[i];
        }

        long leftSum = 0;
        for (int i = 0; i < n - 1; i++) {
            leftSum += nums[i];
            long rightSum = totalSum - leftSum;
            if (leftSum == rightSum) {
                ways++;
            }
        }
        maxWays = Math.max(maxWays, ways);

        // Try changing each element to k
        for (int i = 0; i < n; i++) {
            int[] tempNums = new int[n];
            for (int j = 0; j < n; j++) {
                tempNums[j] = nums[j];
            }
            tempNums[i] = k;

            int tempWays = 0;
            long tempTotalSum = 0;
            for (int j = 0; j < n; j++) {
                tempTotalSum += tempNums[j];
            }

            long tempLeftSum = 0;
            for (int j = 0; j < n - 1; j++) {
                tempLeftSum += tempNums[j];
                long tempRightSum = tempTotalSum - tempLeftSum;
                if (tempLeftSum == tempRightSum) {
                    tempWays++;
                }
            }
            maxWays = Math.max(maxWays, tempWays);
        }

        return maxWays;
    }
}

