public class Solution {
    public int minimumOperations(int[] nums, int start, int goal) {
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{start, 0});
        Set<Integer> visited = new HashSet<>();
        visited.add(start);

        while (!q.isEmpty()) {
            int[] current = q.poll();
            int x = current[0];
            int steps = current[1];

            if (x == goal) {
                return steps;
            }

            for (int num : nums) {
                int[] nextStates = new int[]{
                        x + num,
                        x - num,
                        x ^ num
                };

                for (int nextState : nextStates) {
                    if (nextState >= 0 && nextState <= 1000 && !visited.contains(nextState)) {
                        q.offer(new int[]{nextState, steps + 1});
                        visited.add(nextState);
                    }
                }
            }
        }

        return -1;
    }
}

