import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public int minimumDifference(int[] nums) {
        int n = nums.length / 2;
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }

        List<Integer> subsetSum = new ArrayList<>();
        subsetSum.add(0);

        for (int num : nums) {
            List<Integer> newSubsetSum = new ArrayList<>();
            for (int s : subsetSum) {
                newSubsetSum.add(s);
                newSubsetSum.add(s + num);
            }
            subsetSum = newSubsetSum;
            Collections.sort(subsetSum);
            subsetSum = subsetSum.subList(0, Math.min(subsetSum.size(), n + 1));
        }

        int minDiff = Integer.MAX_VALUE;
        for (int s : subsetSum) {
            minDiff = Math.min(minDiff, Math.abs(sum - 2 * s));
        }

        return minDiff;
    }
}

