import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int countMaxOrSubsets(int[] nums) {
        int maxOr = 0;
        for (int num : nums) {
            maxOr |= num;
        }

        int count = 0;
        List<Integer> subset = new ArrayList<>();
        backtrack(nums, 0, 0, maxOr, subset, count);

        return count;
    }

    private int backtrack(int[] nums, int index, int currentOr, int maxOr, List<Integer> subset, int count) {
        if (index == nums.length) {
            if (currentOr == maxOr && !subset.isEmpty()) {
                return count + 1;
            }
            return count;
        }

        // Include the current element
        subset.add(nums[index]);
        count = backtrack(nums, index + 1, currentOr | nums[index], maxOr, subset, count);
        subset.remove(subset.size() - 1);

        // Exclude the current element
        count = backtrack(nums, index + 1, currentOr, maxOr, subset, count);

        return count;
    }
}

