import java.util.ArrayList;
import java.util.List;

public class Solution {
    public boolean solve(String s1, String s2) {
        if (s1.length() == 0 && s2.length() == 0) {
            return true;
        }
        if (s1.length() == 0 || s2.length() == 0) {
            return false;
        }

        int n1 = s1.length();
        int n2 = s2.length();

        return canDecode(s1, n1) && canDecode(s2, n2) && canMatch(s1, s2);
    }

    private boolean canDecode(String s, int n) {
        if (n == 0) {
            return true;
        }

        boolean[] dp = new boolean[n + 1];
        dp[0] = true;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                if (dp[i - j]) {
                    String sub = s.substring(i - j, i);
                    if (sub.matches("\\d+")) {
                        dp[i] = true;
                        break;
                    } else {
                        dp[i] = true;
                        break;
                    }
                }
            }
        }

        return dp[n];
    }

    private boolean canMatch(String s1, String s2) {
        if (s1.equals(s2)) {
            return true;
        }

        int n1 = s1.length();
        int n2 = s2.length();

        if (n1 == 0 && n2 == 0) {
            return true;
        }

        if (n1 == 0 || n2 == 0) {
            return false;
        }

        return canMatchHelper(s1, s2, 0, 0);
    }

    private boolean canMatchHelper(String s1, String s2, int i, int j) {
        if (i == s1.length() && j == s2.length()) {
            return true;
        }

        if (i == s1.length() || j == s2.length()) {
            return false;
        }

        if (s1.charAt(i) == s2.charAt(j)) {
            return canMatchHelper(s1, s2, i + 1, j + 1);
        }

        if (Character.isDigit(s1.charAt(i))) {
            int k = 1;
            while (i + k < s1.length() && Character.isDigit(s1.charAt(i + k))) {
                k++;
            }
            String numStr = s1.substring(i, i + k);
            int num = Integer.parseInt(numStr);
            if (j + num <= s2.length()) {
                return canMatchHelper(s1, s2, i + k, j + num);
            }
        }

        return false;
    }
}

