import java.util.ArrayList;

public class Solution {
    public String longestSubsequenceRepeatedK(String s, int k) {
        int n = s.length();
        String longestSubsequence = "";

        for (int i = 0; i < (1 << n); i++) {
            StringBuilder subsequence = new StringBuilder();
            for (int j = 0; j < n; j++) {
                if ((i >> j) % 2 == 1) {
                    subsequence.append(s.charAt(j));
                }
            }

            String seqK = "";
            for (int j = 0; j < k; j++) {
                seqK += subsequence.toString();
            }

            if (isSubsequence(seqK, s)) {
                if (subsequence.length() > longestSubsequence.length()) {
                    longestSubsequence = subsequence.toString();
                } else if (subsequence.length() == longestSubsequence.length() && subsequence.toString().compareTo(longestSubsequence) > 0) {
                    longestSubsequence = subsequence.toString();
                }
            }
        }

        return longestSubsequence;
    }

    private boolean isSubsequence(String seq, String s) {
        int i = 0;
        int j = 0;

        while (i < seq.length() && j < s.length()) {
            if (seq.charAt(i) == s.charAt(j)) {
                i++;
            }
            j++;
        }

        return i == seq.length();
    }
}

