public class Solution {
    public int minimumBuckets(String street) {
        int n = street.length();
        int[] buckets = new int[n];
        int count = 0;

        for (int i = 0; i < n; i++) {
            if (street.charAt(i) == 'H') {
                if (i == 0 || i == n - 1) {
                    return -1;
                }
                if (street.charAt(i - 1) == '.') {
                    buckets[i - 1] = 1;
                    count++;
                } else if (street.charAt(i + 1) == '.') {
                    buckets[i + 1] = 1;
                    count++;
                } else {
                    return -1;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (street.charAt(i) == 'H' && buckets[i] == 0) {
                return -1;
            }
        }

        return count;
    }
}

