        nums.offer(num);

        int result = 0;

        ArrayDeque<Integer> tempNums = new ArrayDeque<>(nums);
        ArrayDeque<Character> tempOps = new ArrayDeque<>(ops);

        while (!tempNums.isEmpty()) {
            char op = tempOps.poll();
            int num1 = tempNums.poll();
            if (tempNums.isEmpty()) break;
            int num2 = tempNums.poll();

            if (op == '+') {
                result = num1 + num2;
            } else if (op == '*') {
                result = num1 * num2;
            }

            if(tempNums.isEmpty()){
                break;
            }
        }

        if(result == answer){
            return true;
        }

        return false;
    }
}

