public class Solution {
    public int[] missingRolls(int[] rolls, int mean, int n) {
        int m = rolls.length;
        long sumRolls = 0;
        for (int roll : rolls) {
            sumRolls += roll;
        }

        long totalSum = (long) mean * (n + m);
        long missingSum = totalSum - sumRolls;

        if (missingSum < n || missingSum > 6 * n) {
            return new int[0];
        }

        int[] missingRolls = new int[n];
        int avgMissing = (int) (missingSum / n);
        int remainder = (int) (missingSum % n);

        for (int i = 0; i < n; i++) {
            missingRolls[i] = avgMissing;
        }

        int sum = 0;
        for (int roll : missingRolls) {
            sum += roll;
        }

        int diff = (int) (missingSum - sum);

        for (int i = 0; i < diff; i++) {
            missingRolls[i]++;
        }

        return missingRolls;
    }
}

