import com_github_leetcode.ListNode;
public class Solution {
    public ListNode deleteMiddle(ListNode head) {
        if (head == null) {
            return null;
        }

        ListNode slow = head;
        ListNode fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        if (fast == null) {
            // Odd number of nodes, delete the middle node
            ListNode prev = head;
            while (prev.next != slow) {
                prev = prev.next;
            }
            prev.next = slow.next;
            return head;
        } else {
            // Even number of nodes, delete the middle node
            ListNode prev = head;
            while (prev.next != slow) {
                prev = prev.next;
            }
            prev.next = slow.next;
            return head;
        }
    }
}

