public class Solution {
    public List<Integer> goodDaysToRobBank(int[] security, int time) {
        int n = security.length;
        List<Integer> result = new ArrayList<>();

        if (time > n / 2) {
            return result;
        }

        for (int i = time; i < n - time; i++) {
            boolean nonIncreasingBefore = true;
            for (int j = i - time; j < i; j++) {
                if (security[j] < security[j + 1]) {
                    nonIncreasingBefore = false;
                    break;
                }
            }

            boolean nonDecreasingAfter = true;
            for (int j = i + time; j < i + 2 * time; j++) {
                if (security[j] < security[j - 1]) {
                    nonDecreasingAfter = false;
                    break;
                }
            }

            if (nonIncreasingBefore && nonDecreasingAfter) {
                result.add(i);
            }
        }

        return result;
    }
}

