public class Solution {
    public long kMirror(int k, int n) {
        long sum = 0;
        List<Long> mirrorNumbers = new ArrayList<>();

        for (long i = 1; mirrorNumbers.size() < n; i++) {
            if (isKMirror(i, k)) {
                mirrorNumbers.add(i);
                sum += i;
            }
        }

        return sum;
    }

    private boolean isKMirror(long num, int k) {
        String base10 = String.valueOf(num);
        String baseK = convertToBaseK(num, k);

        return base10.equals(new StringBuilder(base10).reverse().toString()) &&
               baseK.equals(new StringBuilder(baseK).reverse().toString());
    }

    private String convertToBaseK(long num, int k) {
        if (num == 0) {
            return "0";
        }
        StringBuilder sb = new StringBuilder();
        while (num > 0) {
            sb.append(num % k);
            num /= k;
        }
        return sb.reverse().toString();
    }
}

