            int missing = 1;
            while (subtreeValues.contains(missing)) {
                missing++;
            }
            ans[i] = missing;
        }

        return ans;
    }

    private void dfs(int node, List<List<Integer>> adj, int[] nums, Set<Integer> subtreeValues) {
        subtreeValues.add(nums[node]);
        for (int child : adj.get(node)) {
            dfs(child, adj, nums, subtreeValues);
        }
    }
}

