import com_github_leetcode.ListNode;

public class Solution {
    public ListNode reverseEvenLengthGroups(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy;

        int groupNum = 1;
        while (head != null) {
            int groupLength = groupNum;
            int nodesToReverse = groupLength;
            ListNode tail = head;
            for (int i = 1; i < nodesToReverse; i++) {
                if (tail != null) {
                    tail = tail.next;
                } else {
                    break;
                }
            }

            if (nodesToReverse % 2 == 0) {
                ListNode newHead = reverseList(head, tail);
                prev.next = newHead;
                head = tail.next;
                tail.next = head;
            } else {
                prev.next = head;
                head = head.next;
            }

            prev = prev.next;
            groupNum++;
        }

        return dummy.next;
    }

    private ListNode reverseList(ListNode head, ListNode tail) {
        ListNode prev = null;
        ListNode curr = head;
        ListNode next = null;

        while (curr != tail.next) {
            next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }

        return prev;
    }
}

