public class Solution {
    public int[] platesBetweenCandles(String s, int[][] queries) {
        int n = s.length();
        int[] candles = new int[n];
        int candleCount = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '|') {
                candles[candleCount++] = i;
            }
        }

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int left = queries[i][0];
            int right = queries[i][1];

            int leftCandleIndex = -1;
            int rightCandleIndex = -1;

            int j = 0;
            while (j < candleCount) {
                if (candles[j] >= left) {
                    leftCandleIndex = j;
                    break;
                }
                j++;
            }

            j = candleCount - 1;
            while (j >= 0) {
                if (candles[j] <= right) {
                    rightCandleIndex = j;
                    break;
                }
                j--;
            }

            if (leftCandleIndex == -1 || rightCandleIndex == -1 || leftCandleIndex >= rightCandleIndex) {
                answer[i] = 0;
            } else {
                int start = candles[leftCandleIndex] + 1;
                int end = candles[rightCandleIndex];
                int plates = 0;
                for (int k = start; k < end; k++) {
                    if (s.charAt(k) == ' ') {
                        plates++;
                    }
                }
                answer[i] = plates;
            }
        }

        return answer;
    }
}

