import com_github_leetcode.ListNode;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[] nodesBetweenCriticalPoints(ListNode head) {
        List<Integer> criticalPoints = new ArrayList<>();
        ListNode current = head;
        while (current != null && current.next != null) {
            if (current.val > current.prev.val && current.val > current.next.val) {
                criticalPoints.add(getNodeIndex(head, current));
            } else if (current.val < current.prev.val && current.val < current.next.val) {
                criticalPoints.add(getNodeIndex(head, current));
            }
            current = current.next;
        }

        if (criticalPoints.size() < 2) {
            return new int[]{-1, -1};
        }

        int minDistance = Integer.MAX_VALUE;
        int maxDistance = Integer.MIN_VALUE;

        for (int i = 0; i < criticalPoints.size(); i++) {
            for (int j = i + 1; j < criticalPoints.size(); j++) {
                int distance = Math.abs(criticalPoints.get(i) - criticalPoints.get(j));
                minDistance = Math.min(minDistance, distance);
                maxDistance = Math.max(maxDistance, distance);
            }
        }

        return new int[]{minDistance, maxDistance};
    }

    private int getNodeIndex(ListNode head, ListNode node) {
        int index = 0;
        ListNode current = head;
        while (current != node) {
            index++;
            current = current.next;
        }
        return index;
    }
}

