import java.util.HashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;

public class Solution {
    public int[][] validArrangement(int[][] pairs) {
        Map<Integer, Queue<Integer>> graph = new HashMap<>();
        Map<Integer, Integer> inDegree = new HashMap<>();
        Map<Integer, Integer> outDegree = new HashMap<>();

        for (int[] pair : pairs) {
            int start = pair[0];
            int end = pair[1];

            graph.computeIfAbsent(start, k -> new LinkedList<>());
            graph.get(start).offer(end);

            inDegree.put(end, inDegree.getOrDefault(end, 0) + 1);
            outDegree.put(start, outDegree.getOrDefault(start, 0) + 1);
        }

        int startNode = -1;
        for (int[] pair : pairs) {
            int start = pair[0];
            if (outDegree.getOrDefault(start, 0) > 0) {
                startNode = start;
                break;
            }
        }

        if (startNode == -1) {
            startNode = pairs[0][0];
        }

        LinkedList<Integer> result = new LinkedList<>();
        Queue<Integer> stack = new LinkedList<>();
        stack.offer(startNode);

        while (!stack.isEmpty()) {
            int node = stack.poll();
            result.offer(node);

            if (graph.containsKey(node)) {
                Queue<Integer> neighbors = new LinkedList<>(graph.get(node));
                while (!neighbors.isEmpty()) {
                    int neighbor = neighbors.poll();
                    stack.offer(neighbor);
                }
            }
        }

        int[][] arrangedPairs = new int[result.size() - 1][2];
        for (int i = 0; i < arrangedPairs.length; i++) {
            arrangedPairs[i][0] = result.get(i);
            arrangedPairs[i][1] = result.get(i + 1);
        }

        return arrangedPairs;
    }
}

