public class Solution {
    public int countPyramids(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int count = 0;

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                // Check for pyramidal plots
                for (int h = 1; r + h - 1 < m; ++h) {
                    boolean valid = true;
                    for (int i = r; i < r + h; ++i) {
                        for (int j = c - (i - r); j <= c + (i - r); ++j) {
                            if (i >= m || j < 0 || j >= n || grid[i][j] == 0) {
                                valid = false;
                                break;
                            }
                        }
                        if (!valid) break;
                    }
                    if (valid) {
                        count++;
                    }
                }

                // Check for inverse pyramidal plots
                for (int h = 1; r - h + 1 >= 0; ++h) {
                    boolean valid = true;
                    for (int i = r - h + 1; i <= r; ++i) {
                        for (int j = c - (r - i); j <= c + (r - i); ++j) {
                            if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0) {
                                valid = false;
                                break;
                            }
                        }
                        if (!valid) break;
                    }
                    if (valid) {
                        count++;
                    }
                }
            }
        }

        return count;
    }
}

