        TreeNode startNode = nodeMap.get(startValue);
        TreeNode destNode = nodeMap.get(destValue);

        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(startNode, ""));
        Set<TreeNode> visited = new HashSet<>();
        visited.add(startNode);

        while (!queue.isEmpty()) {
            Pair currentPair = queue.poll();
            TreeNode currentNode = currentPair.node;
            String currentPath = currentPath;

            if (currentNode == destNode) {
                return currentPath;
            }

            if (currentNode.left != null) {
                if (!visited.contains(currentNode.left)) {
                    visited.add(currentNode.left);
                    queue.offer(new Pair(currentNode.left, currentPath + "L"));
                }
            }

            if (currentNode.right != null) {
                if (!visited.contains(currentNode.right)) {
                    visited.add(currentNode.right);
                    queue.offer(new Pair(currentNode.right, currentPath + "R"));
                }
            }

            if (currentNode.val != root.val) {
                TreeNode parent = findParent(root, currentNode.val);
                if (parent != null) {
                    if (!visited.contains(parent)) {
                        visited.add(parent);
                        queue.offer(new Pair(parent, currentPath + "U"));
                    }
                }
            }
        }

        return "";
    }

    private void populateNodeMap(TreeNode root, Map<Integer, TreeNode> nodeMap) {
        if (root == null) {
            return;
        }
        nodeMap.put(root.val, root);
        populateNodeMap(root.left, nodeMap);
        populateNodeMap(root.right, nodeMap);
    }

    private TreeNode findParent(TreeNode root, int val) {
        if (root == null || root.val == val) {
            return null;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            TreeNode current = queue.poll();

            if (current.left != null && current.left.val == val) {
                return current;
            }
            if (current.right != null && current.right.val == val) {
                return current;
            }

            if (current.left != null) {
                queue.offer(current.left);
            }
            if (current.right != null) {
                queue.offer(current.right);
            }
        }

        return null;
    }

    private static class Pair {
        TreeNode node;
        String path;

        public Pair(TreeNode node, String path) {
            this.node = node;
            this.path = path;
        }
    }
}

