import java.util.Stack;

public class Solution {
    public String smallestSubsequence(String s, int k, char letter, int repetition) {
        Stack<Character> stack = new Stack<>();
        int letterCount = 0;
        int remainingLength = k;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            while (!stack.isEmpty() && c < stack.peek() && s.length() - i + stack.size() > k && stack.size() >= repetition) {
                if (stack.peek() == letter) {
                    letterCount--;
                }
                stack.pop();
            }

            if (c == letter) {
                letterCount++;
            }

            if (letterCount >= repetition || stack.size() < k) {
                stack.push(c);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (char c : stack) {
            sb.append(c);
        }

        return sb.toString();
    }
}

