public class Solution {
    public boolean winnerOfGame(String colors) {
        int n = colors.length();
        int aMoves = 0;
        int bMoves = 0;

        for (int i = 1; i < n - 1; i++) {
            if (colors.charAt(i) == 'A') {
                if (colors.charAt(i - 1) == 'A' && colors.charAt(i + 1) == 'A') {
                    aMoves++;
                }
            } else {
                if (colors.charAt(i - 1) == 'B' && colors.charAt(i + 1) == 'B') {
                    bMoves++;
                }
            }
        }

        return aMoves > bMoves;
    }
}

