import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int secondMinimum(int n, int[][] edges, int time, int change) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        int[] dist = new int[n + 1];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[1] = 0;

        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{1, 0});

        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int node = curr[0];
            int d = curr[1];

            if (d > dist[node]) continue;

            for (int neighbor : adj.get(node)) {
                int arrivalTime = d + time;
                int signalDuration = change;
                int waitTime = 0;

                if (arrivalTime % change != 0) {
                    waitTime = change - (arrivalTime % change);
                }

                int totalTime = arrivalTime + waitTime;

                if (totalTime < dist[neighbor]) {
                    dist[neighbor] = totalTime;
                    q.offer(new int[]{neighbor, totalTime});
                }
            }
        }

        int minTime = dist[n];
        int secondMinTime = Integer.MAX_VALUE;

        for (int i = 1; i <= n; i++) {
            if (dist[i] > minTime && dist[i] < secondMinTime) {
                secondMinTime = dist[i];
            }
        }

        if (secondMinTime == Integer.MAX_VALUE) {
            return minTime;
        }

        return secondMinTime;
    }
}

