public class Solution {
    public boolean areNumbersAscending(String s) {
        String[] tokens = s.split(" ");
        int prev = -1;
        for (String token : tokens) {
            try {
                int num = Integer.parseInt(token);
                if (num <= prev) {
                    return false;
                }
                prev = num;
            } catch (NumberFormatException e) {
                // Not a number, continue
            }
        }
        return true;
    }
}

