import java.util.Arrays;

public class Solution {
    public int maxTaskAssign(int[] tasks, int[] workers, int pills, int strength) {
        Arrays.sort(tasks);
        Arrays.sort(workers);
        int n = tasks.length;
        int m = workers.length;
        int taskIndex = n - 1;
        int workerIndex = m - 1;
        int completedTasks = 0;
        while (taskIndex >= 0 && workerIndex >= 0) {
            if (workers[workerIndex] >= tasks[taskIndex]) {
                completedTasks++;
                taskIndex--;
                workerIndex--;
            } else {
                if (pills > 0) {
                    if (workers[workerIndex] + strength >= tasks[taskIndex]) {
                        completedTasks++;
                        taskIndex--;
                        workerIndex--;
                        pills--;
                    } else {
                        workerIndex--;
                    }
                } else {
                    workerIndex--;
                }
            }
        }
        return completedTasks;
    }
}
